const CATALOG = {"title":"TwistedPear Handbook","version":"0.1.0","manifestCapabilities":[{"id":"identity","description":"Use an app-scoped identity for signing and addressing."},{"id":"presence","description":"Read coarse peer/interface presence and host info."},{"id":"announce:publish","description":"Publish the app destination."},{"id":"announce:subscribe","description":"Receive announces in the app namespace."},{"id":"lxmf:send","description":"Send LXMF messages from the app destination."},{"id":"lxmf:receive","description":"Receive LXMF messages for the app destination."},{"id":"storage:kv","description":"Store local key/value data for this app."},{"id":"storage:hyperbee","description":"Store ordered local Hyperbee data for this app."},{"id":"resource:fetch","description":"Fetch package resources through host budget rules."},{"id":"workspace","description":"Read and write project source files in this app's private workspace."},{"id":"ai:chat","description":"Send prompts to the host-configured AI service; prompts may include workspace content."},{"id":"share:cas","description":"Store and retrieve bounded content-addressed data shared by 256t id."},{"id":"apps:preview","description":"Run a built app in the host's sandboxed dev-preview slot."},{"id":"apps:package","description":"Package and sign apps under this device's publisher identity (asks each time)."},{"id":"apps:publish","description":"Publish signed apps so other users can find and install them (asks each time)."},{"id":"apps:install","description":"Ask the host to install apps from a 256t id (asks each time, with capability review)."}],"parts":[{"id":"part-1-concepts","title":"Part I — Concepts","chapters":[{"id":"what-is-twistedpear","title":"What TwistedPear is"},{"id":"reticulum-fundamentals","title":"Reticulum fundamentals"},{"id":"pears-bulk-plane","title":"Pears bulk plane"},{"id":"concepts-in-practice","title":"Concepts in practice"}]},{"id":"part-2-hosts","title":"Part II — The hosts","chapters":[{"id":"host-android","title":"Android host"},{"id":"host-ios","title":"iOS host"},{"id":"host-desktop","title":"Desktop host"},{"id":"host-web","title":"Web host"},{"id":"host-headless","title":"Headless node & seeder"},{"id":"difference-matrix","title":"Live difference matrix"}]},{"id":"part-3-sdk","title":"Part III — Developing mini-apps","chapters":[{"id":"sdk-identity","title":"Identity & signing"},{"id":"sdk-presence","title":"Presence"},{"id":"sdk-storage-kv","title":"Key/value storage"},{"id":"sdk-storage-hyperbee","title":"Hyperbee storage"},{"id":"sdk-lxmf","title":"LXMF messaging"},{"id":"sdk-announce","title":"Announce & subscribe"},{"id":"sdk-resource-fetch","title":"Resource fetch"},{"id":"sdk-budgets","title":"Budgets & quotas"},{"id":"sdk-workspace","title":"Workspace"},{"id":"sdk-share-cas","title":"Content-addressed share"},{"id":"sdk-capabilities","title":"Capability model"},{"id":"sdk-apps-package","title":"Packaging & preview"},{"id":"sdk-apps-publish","title":"Publish & install"},{"id":"sdk-devstudio","title":"DevStudio walkthrough"},{"id":"sdk-ai-chat","title":"AI chat"},{"id":"sdk-widget-gallery","title":"Widget gallery"}]},{"id":"part-4-diagnostics","title":"Part IV — Diagnostics","chapters":[{"id":"running-diagnostics","title":"Running diagnostics"},{"id":"device-gated-probes","title":"Device-gated probes"}]},{"id":"part-5-reference","title":"Part V — Reference","chapters":[{"id":"ref-capabilities","title":"Capabilities"},{"id":"ref-widgets","title":"Widget protocol"},{"id":"ref-host-api","title":"Host API"},{"id":"ref-packages","title":"Package format"},{"id":"ref-interfaces","title":"Network interfaces"},{"id":"ref-quotas","title":"Quotas & limits"},{"id":"ref-host-config","title":"Host configuration"},{"id":"ref-cli","title":"CLI commands"}]}],"chapters":[{"id":"what-is-twistedpear","title":"What TwistedPear is","partId":"part-1-concepts","partTitle":"Part I — Concepts","blocks":[{"type":"heading","level":1,"text":"What TwistedPear is"},{"type":"paragraph","text":"TwistedPear is a peer-to-peer app platform. A **host** on each device is a full Reticulum peer; **mini-apps** are sandboxed JavaScript bundles that talk to the host only through the SDK."},{"type":"heading","level":2,"text":"Two planes"},{"type":"list","items":["**Control plane** — Reticulum handles identity, announces, links, LXMF, and"]},{"type":"paragraph","text":"off-grid Resource transfer."},{"type":"list","items":["**Bulk plane** — Hypercore / Hyperdrive / Hyperswarm carry large package"]},{"type":"paragraph","text":"syncs when IP connectivity exists. Pears bulk plane."},{"type":"chapter-link","label":"Pears bulk plane","chapterId":"pears-bulk-plane"},{"type":"heading","level":2,"text":"Trust model"},{"type":"paragraph","text":"Publisher identity **is** network identity. Packages are Ed25519-signed with the developer's Reticulum key, so discovering an app and trusting its author use the same root."},{"type":"heading","level":2,"text":"This Handbook"},{"type":"paragraph","text":"This document is itself a mini-app. If it installed and rendered on *this* host, you have already exercised packaging, install, sandbox, broker, and the widget renderer. Chapters later add interactive applets that probe live capabilities."},{"type":"paragraph","text":"Open **Diagnostics** from the table of contents to run every probe, export a report, or compare against another device. Reference pages in Part V are generated from the same runtime sources the host uses. Host-specific behavior: Part II — The hosts."},{"type":"chapter-link","label":"Part II — The hosts","chapterId":"host-desktop"}]},{"id":"reticulum-fundamentals","title":"Reticulum fundamentals","partId":"part-1-concepts","partTitle":"Part I — Concepts","blocks":[{"type":"heading","level":1,"text":"Reticulum fundamentals"},{"type":"paragraph","text":"Reticulum is a cryptography-based networking stack designed for constrained and unreliable links. TwistedPear uses it as the only hard networking constraint."},{"type":"heading","level":2,"text":"Building blocks"},{"type":"list","items":["**Identity** — an X25519/Ed25519 keypair. Destinations are derived hashes.","**Announce** — a signed public advertisement that a destination is reachable.","**Link** — an encrypted channel between two destinations.","**Resource** — a bulk transfer over a link (used when Hyperswarm is unavailable).","**LXMF** — store-and-forward messaging on top of Reticulum."]},{"type":"heading","level":2,"text":"App-scoped destinations"},{"type":"paragraph","text":"Mini-apps never hold private keys. The host derives an **app destination** from the device identity plus the app id. Bulk transfer when IP is available: Pears bulk plane. See Concepts in practice for a live identity probe, or Identity & signing."},{"type":"chapter-link","label":"Pears bulk plane","chapterId":"pears-bulk-plane"},{"type":"chapter-link","label":"Concepts in practice","chapterId":"concepts-in-practice"},{"type":"chapter-link","label":"Identity & signing","chapterId":"sdk-identity"}]},{"id":"pears-bulk-plane","title":"Pears bulk plane","partId":"part-1-concepts","partTitle":"Part I — Concepts","blocks":[{"type":"heading","level":1,"text":"Pears bulk plane"},{"type":"paragraph","text":"Reticulum is the **control plane** — identity, announces, links, LXMF, and off-grid Resource transfer. When IP connectivity exists, large package syncs prefer the **Pears bulk plane**: Hypercore, Hyperdrive, and Hyperswarm."},{"type":"heading","level":2,"text":"Why two planes"},{"type":"paragraph","text":"Reticulum links are optimized for constrained carriers (BLE, LoRa) with small MTUs and high latency. Shipping a multi-megabyte `.tpkg` over those links works but is slow. Hyperswarm discovery plus Hyperdrive replication uses TCP where available and falls back to Reticulum Resources when it is not."},{"type":"heading","level":2,"text":"Building blocks"},{"type":"list","items":["**Hypercore** — append-only signed logs. Each app package is a deterministic"]},{"type":"paragraph","text":"archive keyed by the publisher's feed."},{"type":"list","items":["**Hyperdrive** — a filesystem view over one or more Hypercores. `tp publish`"]},{"type":"paragraph","text":"seeds the signed `.tpkg`; peers replicate blocks from seeders on the LAN or DHT."},{"type":"list","items":["**Hyperswarm** — topic-based peer discovery for Hyperdrive replication. Desktop"]},{"type":"paragraph","text":"and headless hosts run seeders by default; phones are usually leaf consumers."},{"type":"heading","level":2,"text":"In practice"},{"type":"table","headers":["Operation","Typical plane"],"rows":[["Discover an app announce","Reticulum control plane"],["Install over LAN / internet","Hyperdrive bulk fetch"],["Install with no IP path","Reticulum Resource transfer"],["LXMF chat message","Reticulum only"],["Handbook diagnostic report (`share.put`)","CAS + optional Hyperdrive seed"]]},{"type":"paragraph","text":"Headless seeding: Headless node & seeder. Distribution tutorial: Publish & install."},{"type":"chapter-link","label":"Headless node & seeder","chapterId":"host-headless"},{"type":"chapter-link","label":"Publish & install","chapterId":"sdk-apps-publish"}]},{"id":"concepts-in-practice","title":"Concepts in practice","partId":"part-1-concepts","partTitle":"Part I — Concepts","blocks":[{"type":"heading","level":1,"text":"Concepts in practice"},{"type":"paragraph","text":"The applets below run on **this** host — the same probes used in Part III and Part IV diagnostics, grouped for readers who want to see Reticulum building blocks work before diving into SDK chapters."},{"type":"heading","level":2,"text":"Identity"},{"type":"applet","appletId":"identity-hash"},{"type":"heading","level":2,"text":"Announce loop"},{"type":"applet","appletId":"announce-loop"},{"type":"heading","level":2,"text":"LXMF self-message"},{"type":"applet","appletId":"lxmf-roundtrip"},{"type":"paragraph","text":"Next: Identity & signing · Running diagnostics"},{"type":"chapter-link","label":"Identity & signing","chapterId":"sdk-identity"},{"type":"chapter-link","label":"Running diagnostics","chapterId":"running-diagnostics"}]},{"id":"host-android","title":"Android host","partId":"part-2-hosts","partTitle":"Part II — The hosts","blocks":[{"type":"heading","level":1,"text":"Android host"},{"type":"paragraph","text":"The Android host is a React Native shell around the same **Bare worklet** used on iOS and desktop. Reticulum, LXMF, catalog install, and the mini-app runtime all run in the worklet; the JVM layer supplies lifecycle, BLE, multicast bridges, and a foreground service so the node can stay reachable in the background."},{"type":"heading","level":2,"text":"Architecture"},{"type":"list","items":["**Expo / RN shell** — settings, grants, confirmations, widget renderer.","**Bare worklet child** — `reticulum-ts`, `host-core` leaf roles, broker, sandboxes.","**Native bridges** — TCP, AutoInterface multicast, Bonjour, BLE central/peripheral,"]},{"type":"paragraph","text":"RNode serial-over-BLE, camera (QR install)."},{"type":"heading","level":2,"text":"Roles"},{"type":"paragraph","text":"Android phones default to **leaf** peers: transport routing and package seeding are off unless the operator enables them on a dedicated device. Most users run a leaf that dials LAN peers or a desktop gateway."},{"type":"heading","level":2,"text":"Lifecycle"},{"type":"list","items":["**Foreground** — full interface set, mini-app execution, BLE active.","**Background** — `NodeForegroundService` keeps the worklet alive; interfaces"]},{"type":"paragraph","text":"quiesce on a grace timer then reconnect on resume (see LIMITATIONS.md §6)."},{"type":"list","items":["**Suspended** — no mini-app execution; LXMF store-and-forward only."]},{"type":"heading","level":2,"text":"Storage"},{"type":"paragraph","text":"App data lives under the host's private app storage. Identity keys and package archives are worklet-managed; clearing app data resets the peer."},{"type":"heading","level":2,"text":"What to expect on this host"},{"type":"paragraph","text":"Use the live difference matrix on a real device or emulator — `host.info()` reports `platform=android`, interface types, and roles for **this** install. BLE pair, RNode, multicast, and camera probes are device-gated in CI."},{"type":"chapter-link","label":"live difference matrix","chapterId":"difference-matrix"},{"type":"chapter-link","label":"device-gated","chapterId":"device-gated-probes"}]},{"id":"host-ios","title":"iOS host","partId":"part-2-hosts","partTitle":"Part II — The hosts","blocks":[{"type":"heading","level":1,"text":"iOS host"},{"type":"paragraph","text":"The iOS host mirrors Android: a React Native shell supervising a **Bare worklet** with the same protocol stack. Platform entitlements and background rules shape which interfaces stay online when the app is not in the foreground."},{"type":"heading","level":2,"text":"Architecture"},{"type":"list","items":["**Expo / RN shell** — peer browser, grants, confirmations, widget renderer.","**Bare worklet child** — identical broker and sandbox model to Android/desktop.","**Native bridges** — TCP client, Bonjour, BLE (central/peripheral), RNode"]},{"type":"paragraph","text":"over BLE only (no USB serial on iOS)."},{"type":"heading","level":2,"text":"Lifecycle (no foreground-service equivalent)"},{"type":"paragraph","text":"iOS has no Android-style foreground service. Backgrounding is a **state transition**:"},{"type":"list","items":["**Foreground** — interfaces and the active mini-app run normally.","**Background grace** — native lifecycle sends `suspend-node`; worklet quiesces"]},{"type":"paragraph","text":"TCP/multicast timers; existing BLE links may survive briefly."},{"type":"list","items":["**Suspended** — no mini-app execution; pending LXMF is persisted for later sync."]},{"type":"paragraph","text":"Store-posture builds refuse catalog install and dev side-load; development builds keep parity with Android for `tp dev` and Handbook installs."},{"type":"heading","level":2,"text":"Entitlements"},{"type":"paragraph","text":"Local network, Bonjour (`_reticulum._udp`), Bluetooth, and multicast require usage strings and (for multicast) the networking multicast entitlement. Until entitlement filing completes, multicast may report unavailable even though the code path exists — check `host.info()` on **this** device."},{"type":"heading","level":2,"text":"Simulator vs device"},{"type":"paragraph","text":"The simulator validates worklet boot, TCP/localhost, store-posture refusal, and Handbook software-tier slices. BLE, real background timing, and LAN multicast need hardware — see Device-gated probes."},{"type":"chapter-link","label":"Device-gated probes","chapterId":"device-gated-probes"},{"type":"paragraph","text":"Compare live signals: Live difference matrix."},{"type":"chapter-link","label":"Live difference matrix","chapterId":"difference-matrix"}]},{"id":"host-desktop","title":"Desktop host","partId":"part-2-hosts","partTitle":"Part II — The hosts","blocks":[{"type":"heading","level":1,"text":"Desktop host"},{"type":"paragraph","text":"The desktop host is the **always-on peer** in a typical mesh: transport routing, package seeding, optional LXMF propagation, and a gateway for browser tabs via the WebSocket Reticulum interface."},{"type":"heading","level":2,"text":"Architecture"},{"type":"list","items":["**Electron shell** (`apps/host-desktop`) — tray, power events, native multicast/"]},{"type":"paragraph","text":"Bonjour bridges, crash supervision, DOM widget renderer."},{"type":"list","items":["**Bare worklet child** — same stack as mobile; stdio IPC to the shell.","**`host-core`** — shared engine with headless `tp node` / `tp seed`."]},{"type":"heading","level":2,"text":"Default roles"},{"type":"table","headers":["Role","Default","Notes"],"rows":[["Transport node","on","Off when `--attach-rnsd` leaf mode"],["Seeder / LAN mirror","on","Quota'd Hyperdrive serving"],["Propagation server","off","Enable in UI or `--propagation`"],["WebSocket gateway","off","`--ws-listen` for web-host tabs"]]},{"type":"heading","level":2,"text":"Lifecycle"},{"type":"list","items":["**Suspend** (system sleep) — worklet quiesces interfaces.","**Resume** — reconnect and re-announce.","**Crash** — supervisor restarts the worklet with exponential backoff."]},{"type":"heading","level":2,"text":"First-boot apps"},{"type":"paragraph","text":"Fresh desktop installs seed **handbook**, **devstudio**, and **chat** from the TwistedPear platform publisher. Open **Installed** and launch **handbook** — you are reading it."},{"type":"heading","level":2,"text":"Config & data"},{"type":"paragraph","text":"Platform data directory (identity, `config.json`, quotas):"},{"type":"list","items":["macOS: `~/Library/Application Support/TwistedPear/host`","Linux: `~/.local/share/twistedpear/host`","Windows: `%APPDATA%/TwistedPear/host`"]},{"type":"paragraph","text":"Full schema: Host configuration."},{"type":"chapter-link","label":"Host configuration","chapterId":"ref-host-config"},{"type":"paragraph","text":"Opt-in status JSON: `http://127.0.0.1:9473/status` when `--status-endpoint` is set."},{"type":"paragraph","text":"Live capability view: Live difference matrix. Details: docs/desktop-host.md."},{"type":"chapter-link","label":"Live difference matrix","chapterId":"difference-matrix"}]},{"id":"host-web","title":"Web host","partId":"part-2-hosts","partTitle":"Part II — The hosts","blocks":[{"type":"heading","level":1,"text":"Web host"},{"type":"paragraph","text":"The web host is a **browser tab** running the full mini-app stack in-page — not a remote UI for another node. `reticulum-ts` executes in a core Web Worker; per-app sandboxes use opaque-origin iframes plus workers; the host UI renders widgets with React Native for Web."},{"type":"heading","level":2,"text":"Leaf-only posture"},{"type":"paragraph","text":"Browsers cannot accept inbound connections or open raw TCP/UDP. The web host is permanently a **leaf peer**:"},{"type":"list","items":["No transport-node, seeder, or propagation roles — ever.","Reticulum reachability goes through a **WebSocket gateway** on a desktop or"]},{"type":"paragraph","text":"`tp node` peer (`--ws-listen`)."},{"type":"list","items":["Bulk installs use the gateway's `/bulk-fetch` proxy; offline fallback is"]},{"type":"paragraph","text":"Reticulum Resource transfer."},{"type":"heading","level":2,"text":"Architecture"},{"type":"code","documentId":"chapters/host-web/sample-0.txt","language":"text"},{"type":"heading","level":2,"text":"Security notes"},{"type":"paragraph","text":"Identity keys live in IndexedDB encrypted with WebCrypto — weaker than a hardware keystore. The **page origin is part of the trust base**: default posture is self-serving from your own node (`tp node --serve-web`). See LIMITATIONS.md §8."},{"type":"heading","level":2,"text":"Radios & serial"},{"type":"paragraph","text":"No BLE peripheral, no multicast AutoInterface. WebSerial RNode (Chromium) is a stretch path; real USB LoRa E2E is device-gated. Probes report `unavailable` honestly on `platform=web`."},{"type":"paragraph","text":"Gateway spec: WebSocket interface. Live matrix: Live difference matrix."},{"type":"chapter-link","label":"WebSocket interface","chapterId":"ref-interfaces"},{"type":"chapter-link","label":"Live difference matrix","chapterId":"difference-matrix"}]},{"id":"host-headless","title":"Headless node & seeder","partId":"part-2-hosts","partTitle":"Part II — The hosts","blocks":[{"type":"heading","level":1,"text":"Headless node & seeder"},{"type":"paragraph","text":"`tp node` and `tp seed` run **`host-core`** without a UI — the same engine as the desktop worklet, suitable for servers, CI, and LAN gateways."},{"type":"heading","level":2,"text":"`tp node`"},{"type":"paragraph","text":"Always-on desktop-class peer from the CLI:"},{"type":"code","documentId":"chapters/host-headless/sample-0.txt","language":"text"},{"type":"paragraph","text":"Common flags:"},{"type":"list","items":["`--no-transport` / `--no-seeder` — leaf or attach-only modes","`--ws-listen [host:]port` — WebSocket gateway for browser tabs","`--ws-token <token>` — optional shared secret on the gateway","`--serve-web [dir]` — serve the built web-host bundle from this machine","`--status-endpoint` — localhost JSON status on port 9473"]},{"type":"heading","level":2,"text":"`tp seed`"},{"type":"paragraph","text":"Headless package mirror focused on Hyperdrive seeding:"},{"type":"code","documentId":"chapters/host-headless/sample-1.txt","language":"text"},{"type":"paragraph","text":"Use when you want seeding without the Electron shell. Quotas match desktop defaults (see Quotas & limits)."},{"type":"chapter-link","label":"Quotas & limits","chapterId":"ref-quotas"},{"type":"heading","level":2,"text":"When to use headless vs desktop"},{"type":"table","headers":["Need","Headless","Desktop host"],"rows":[["WebSocket gateway for web tabs","`tp node --ws-listen`","enable in config / CLI"],["Tray UI + crash supervision","—","Electron shell"],["CI / docker interop","`tp node` in containers","optional"],["Developer mini-app side-load","`tp dev` targets either","`tp dev`"]]},{"type":"heading","level":2,"text":"Handbook on node"},{"type":"paragraph","text":"CI runs the Handbook with `npm run test:handbook` — pack, install, render every chapter, execute applets on the Node Worker sandbox backend. This is the same catalog desktop seeds, without graphics."},{"type":"paragraph","text":"CLI reference: CLI commands."},{"type":"chapter-link","label":"CLI commands","chapterId":"ref-cli"}]},{"id":"difference-matrix","title":"Live difference matrix","partId":"part-2-hosts","partTitle":"Part II — The hosts","blocks":[{"type":"heading","level":1,"text":"Live difference matrix"},{"type":"paragraph","text":"Hosts share one SDK and widget protocol, but platform sandboxes and entitlements shape what is actually available. Per-host chapters describe architecture and lifecycle; `host.info()` returns the facts for **this** host — platform id, host / API versions, enabled roles, interface types, and quota snapshot — instead of asserting differences in stale prose."},{"type":"list","items":["Android host · iOS host ·"]},{"type":"paragraph","text":"Desktop host · Web host · Headless node & seeder"},{"type":"chapter-link","label":"Desktop host","chapterId":"host-desktop"},{"type":"chapter-link","label":"Web host","chapterId":"host-web"},{"type":"chapter-link","label":"Headless node & seeder","chapterId":"host-headless"},{"type":"heading","level":2,"text":"Probe"},{"type":"applet","appletId":"host-info"},{"type":"heading","level":2,"text":"How to read differences"},{"type":"table","headers":["Signal","Typical cause","See also"],"rows":[["`platform=web` + no `auto`/`ble`","Browser leaf: WebSocket gateway only","[Web host](chapter:host-web), [LIMITATIONS.md](../../../LIMITATIONS.md) §8"],["`platform=ios` + missing multicast","Multicast entitlement / Bonjour path","[iOS host](chapter:host-ios), LIMITATIONS §6"],["`transport=false` on phones","Leaf role; desktops default transport + seeder","[Android](chapter:host-android) / [Desktop](chapter:host-desktop)"],["Interface listed but offline","Feature present; peer/hardware not connected","Part IV diagnostics"],["`not-granted` applet cards","User withheld a manifest capability","[Capability model](chapter:sdk-capabilities)"],["BLE / RNode / camera `device-gated`","Hardware or second device required","[Device-gated probes](chapter:device-gated-probes)"],["Large install over BLE slow","Bulk plane vs Resource fallback","[Budgets & quotas](chapter:sdk-budgets)"]]},{"type":"paragraph","text":"Cross-check with presence (`presence.snapshot`) and Part IV diagnostics: run all applets, export a report via `share:cas`, then paste another device's 256t id to diff results side-by-side."}]},{"id":"sdk-identity","title":"Identity & signing","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Identity & signing"},{"type":"paragraph","text":"The `identity` capability grants an app-scoped destination and brokered signing. Private keys never enter the sandbox."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-identity/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"paragraph","text":"The applet below calls `identity.destinationHash()` on this host and reports pass / fail / not-granted."},{"type":"applet","appletId":"identity-hash"},{"type":"paragraph","text":"Use **Open in DevStudio** on any applet to copy the sample into a DevStudio project via `share:cas`. Concept overview: Concepts in practice."},{"type":"chapter-link","label":"Concepts in practice","chapterId":"concepts-in-practice"}]},{"id":"sdk-presence","title":"Presence","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Presence"},{"type":"paragraph","text":"The `presence` capability lets a mini-app read coarse peer and interface state and host metadata (`host.info`) without raw sockets or interface handles."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-presence/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"presence-snapshot"},{"type":"paragraph","text":"See also the live difference matrix (`host.info`)."},{"type":"chapter-link","label":"live difference matrix","chapterId":"difference-matrix"}]},{"id":"sdk-storage-kv","title":"Key/value storage","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Key/value storage"},{"type":"paragraph","text":"`storage:kv` is a per-app local store with a byte quota enforced by the host."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-storage-kv/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"storage-kv"}]},{"id":"sdk-storage-hyperbee","title":"Hyperbee storage","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Hyperbee storage"},{"type":"paragraph","text":"`storage:hyperbee` opens a local-only ordered key/value store (Hyperbee) namespaced to the app. Keys stay sorted so list ranges are useful for feeds and indexes."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-storage-hyperbee/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"storage-hyperbee"}]},{"id":"sdk-lxmf","title":"LXMF messaging","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"LXMF messaging"},{"type":"paragraph","text":"`lxmf:send` and `lxmf:receive` give a mini-app a namespaced mailbox. Private keys stay in the host; the app only sees deliveries for its destination."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-lxmf/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"lxmf-roundtrip"},{"type":"paragraph","text":"See also Identity & signing."},{"type":"chapter-link","label":"Identity & signing","chapterId":"sdk-identity"}]},{"id":"sdk-announce","title":"Announce & subscribe","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Announce & subscribe"},{"type":"paragraph","text":"Announces are how destinations advertise reachability. Mini-apps publish and subscribe in an app namespace through the host broker."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-announce/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"announce-loop"}]},{"id":"sdk-resource-fetch","title":"Resource fetch","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Resource fetch"},{"type":"paragraph","text":"`resource:fetch` asks the host to pull a Resource through its budget rules. The mini-app never sees sockets or peer handles — only bytes (or a typed error)."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-resource-fetch/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"resource-fetch"}]},{"id":"sdk-budgets","title":"Budgets & quotas","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Budgets & quotas"},{"type":"paragraph","text":"Hosts enforce limits at several layers so constrained links (BLE, LoRa) and shared devices stay predictable. Budgets are not optional hints — exceeding them returns typed errors or truncated transfers."},{"type":"heading","level":2,"text":"Resource fetch (per call)"},{"type":"paragraph","text":"`resource:fetch` takes an explicit `budgetBytes` cap. The host pulls through its link strategy without exposing sockets to the sandbox."},{"type":"code","documentId":"chapters/sdk-budgets/sample-0.js","language":"javascript"},{"type":"applet","appletId":"resource-fetch"},{"type":"heading","level":2,"text":"Package install (per transport)"},{"type":"paragraph","text":"`conformance/budgets/measured.json` records install time at measured bitrates. The BLE guidance target is ~180 KiB for under-one-minute installs; this full Handbook is ~165 KiB (~55 s at measured BLE rates) — intentionally above the tiny-app example budget."},{"type":"table","headers":["Package","Size","LAN","BLE","RNode"],"rows":[["tiny hello","< 1 KiB","~1 s","~1 s","~6 s"],["handbook (full)","~165 KiB","~1 s","~55 s","~19 min"]]},{"type":"paragraph","text":"Split per-part Handbook packages if BLE install of the full catalog matters."},{"type":"heading","level":2,"text":"Host & workspace quotas"},{"type":"paragraph","text":"Node seeding, propagation store, bandwidth caps, workspace file limits, widget tree size, and AI message caps are listed in Quotas & limits. Override desktop/node defaults in `<data-dir>/config.json` — see Host configuration."},{"type":"chapter-link","label":"Quotas & limits","chapterId":"ref-quotas"},{"type":"chapter-link","label":"Host configuration","chapterId":"ref-host-config"}]},{"id":"sdk-workspace","title":"Workspace","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Workspace"},{"type":"paragraph","text":"`workspace` is a private per-app project filesystem of relative paths (strings; 256 KiB/file, 4 MiB and 512 files per app). DevStudio and this Handbook use it for sources and applet seeds."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-workspace/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"workspace-rw"}]},{"id":"sdk-share-cas","title":"Content-addressed share","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Content-addressed share"},{"type":"paragraph","text":"`share:cas` stores a bounded string and returns a 94-character 256t id. Paste or scan that id on another device to `share.get` the same bytes — diagnostics reports and DevStudio hand-offs use this path."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-share-cas/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"share-cas"}]},{"id":"sdk-capabilities","title":"Capability model","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Capability model"},{"type":"paragraph","text":"Mini-apps declare every SDK surface they may use in `app.manifest.json`. At install the host shows the full list; the user may grant a **subset**. The broker enforces grants on every call — withheld capabilities are not errors in the Handbook, they become `not-granted` teaching cards."},{"type":"heading","level":2,"text":"Manifest"},{"type":"code","documentId":"chapters/sdk-capabilities/sample-0.json","language":"json"},{"type":"paragraph","text":"Only ids from `CAPABILITY_DEFINITIONS` are valid. The reference list is generated at build time: Capabilities."},{"type":"chapter-link","label":"Capabilities","chapterId":"ref-capabilities"},{"type":"heading","level":2,"text":"Typed errors"},{"type":"paragraph","text":"The runtime throws `CapabilityError` with a stable `code`:"},{"type":"table","headers":["Code","Meaning"],"rows":[["`UNKNOWN_CAPABILITY`","Manifest names a capability the host does not recognize"],["`UNDECLARED_CAPABILITY`","Code calls a capability not listed in the manifest"],["`CAPABILITY_DENIED`","Manifest lists it but the user withheld the grant"]]},{"type":"code","documentId":"chapters/sdk-capabilities/sample-1.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"paragraph","text":"Withhold `identity` at install (or tap **Revoke** in host settings) and re-run the applet — it reports `not-granted` instead of throwing into your UI."},{"type":"applet","appletId":"identity-hash"},{"type":"paragraph","text":"Double-gated capabilities (`apps:package`, `apps:publish`, `apps:install`, `apps:preview`) also require a host-chrome confirmation the sandbox cannot dismiss. See Packaging & preview."},{"type":"chapter-link","label":"Packaging & preview","chapterId":"sdk-apps-package"}]},{"id":"sdk-apps-package","title":"Packaging & preview","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Packaging & preview"},{"type":"paragraph","text":"`apps:package` and `apps:preview` are double-gated: the capability grant plus a host-chrome confirmation the mini-app cannot dismiss. Package signs under the device publisher identity; preview runs the project in the single sandboxed dev-preview slot."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-apps-package/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"paragraph","text":"Use **Run applet** for the automated inline probe (package → preview → stop, used in CI)."},{"type":"paragraph","text":"Use **Run as real app** to launch the sample in the host dev-preview slot — the full sandbox/grant/launch loop with host confirmation. Stop preview when finished."},{"type":"applet","appletId":"apps-package-preview"}]},{"id":"sdk-apps-publish","title":"Publish & install","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Publish & install"},{"type":"paragraph","text":"`apps:publish` announces a packaged 256t id under the publisher identity. `apps:install` asks the host to fetch, verify, and review capabilities before anything runs. Both raise a confirmation dialog on every call."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-apps-publish/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"applet","appletId":"apps-publish-install"}]},{"id":"sdk-devstudio","title":"DevStudio walkthrough","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"DevStudio walkthrough"},{"type":"paragraph","text":"DevStudio is a mini-app IDE — same sandbox and capability model as any other app. Desktop first-boot seeds it alongside this Handbook."},{"type":"heading","level":2,"text":"Development loop"},{"type":"paragraph","text":"1. **New project** — DevStudio seeds `hello-app/app.json` + `bundle.js` in the app workspace. 2. **Edit** — the `code-editor` widget is content-by-reference: the tree carries a `documentId`; edits flow back as events and persist with `workspace.write`. 3. **AI assist** — with `ai:chat` granted, describe a change; the host holds the API key and model (never in the sandbox). Review whole-file proposals before **Apply**. 4. **Preview** — `apps:preview` runs the project in the single dev-preview slot while DevStudio keeps running. 5. **Package & sign** — host confirmation; deterministic `.tpkg` under the device publisher identity; 256t id + QR. 6. **Publish** — host confirmation; seed on Hyperdrive and announce the locator."},{"type":"heading","level":2,"text":"Open in DevStudio from the Handbook"},{"type":"paragraph","text":"Every applet card includes **Open in DevStudio**. The Handbook exports the applet source plus a `tp.devstudio.workspace.v1` handoff via `share:cas`; paste or scan the QR in DevStudio to import the sample as a starting project."},{"type":"paragraph","text":"Try it on the identity probe below, then continue in DevStudio with Packaging & preview."},{"type":"chapter-link","label":"Packaging & preview","chapterId":"sdk-apps-package"},{"type":"applet","appletId":"identity-hash"}]},{"id":"sdk-ai-chat","title":"AI chat","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"AI chat"},{"type":"paragraph","text":"`ai:chat` sends prompts to the host-configured OpenRouter-compatible endpoint. The host clamps budgets, enforces a model allowlist, and allows one in-flight request per app. The API key never enters the sandbox."},{"type":"heading","level":2,"text":"API"},{"type":"code","documentId":"chapters/sdk-ai-chat/sample-0.js","language":"javascript"},{"type":"heading","level":2,"text":"Live probe"},{"type":"paragraph","text":"Hosts without an AI endpoint report `unavailable`. When configured, the applet below exercises a single round-trip."},{"type":"applet","appletId":"ai-chat"}]},{"id":"sdk-widget-gallery","title":"Widget gallery","partId":"part-3-sdk","partTitle":"Part III — Developing mini-apps","blocks":[{"type":"heading","level":1,"text":"Widget gallery"},{"type":"paragraph","text":"The widget protocol is the cross-platform UI seam. Allowed components: `view`, `text`, `image`, `button`, `text-input`, `switch`, `scroll`, `list`, `progress`, `divider`, `spacer`, `code-editor`, `qr-code`."},{"type":"paragraph","text":"`code-editor` is content-by-reference (workspace `documentId`); `qr-code` is sized for 94-character 256t ids. The host rejects unknown props, styles, duplicate ids, and oversized trees."},{"type":"heading","level":2,"text":"Live probe"},{"type":"paragraph","text":"The applet submits a tree that includes every component type. After it reports, the Handbook re-renders this chapter with the result card."},{"type":"applet","appletId":"widget-gallery"}]},{"id":"running-diagnostics","title":"Running diagnostics","partId":"part-4-diagnostics","partTitle":"Part IV — Diagnostics","blocks":[{"type":"heading","level":1,"text":"Running diagnostics"},{"type":"paragraph","text":"Each applet reports `{ appletId, status, details, timings }` with first-class `unavailable` and `not-granted` outcomes."},{"type":"heading","level":2,"text":"On this screen"},{"type":"paragraph","text":"From the Handbook **Contents**, use:"},{"type":"list","items":["**Run all diagnostics** — runs every catalog applet inline on this host, grouped"]},{"type":"paragraph","text":"by area (crypto, interfaces, storage, distribution, runtime)"},{"type":"list","items":["**Export report** — packs host info + results into JSON, stores via `share.put`,"]},{"type":"paragraph","text":"shows a 256t id / QR"},{"type":"list","items":["**Compare report** — paste another device's report id to render a status matrix"]},{"type":"paragraph","text":"Open an SDK chapter and tap **Run applet** for a single probe."},{"type":"heading","level":2,"text":"Software-tier probes"},{"type":"list","items":["Host info — `host.info` (`presence`)","App destination hash — `identity`","Presence snapshot — `presence`","KV round-trip — `storage:kv`","Hyperbee round-trip — `storage:hyperbee`","LXMF self-message — `identity`, `lxmf:*`","Announce publish/subscribe — `announce:*`","Resource fetch — `resource:fetch`","Workspace read/write — `workspace`","CAS share — `share:cas`","Package + preview — `apps:package`, `apps:preview`","Publish + install — `apps:publish`, `apps:install`","AI chat — `ai:chat`","Widget gallery — widget protocol"]},{"type":"paragraph","text":"Device-gated probes (BLE peer, RNode, multicast, camera QR) live in Device-gated probes — they report `unavailable` in CI and simulators with guided procedures for real hardware."},{"type":"chapter-link","label":"Device-gated probes","chapterId":"device-gated-probes"}]},{"id":"device-gated-probes","title":"Device-gated probes","partId":"part-4-diagnostics","partTitle":"Part IV — Diagnostics","blocks":[{"type":"heading","level":1,"text":"Device-gated probes"},{"type":"paragraph","text":"These applets need **real hardware or a guided manual step** on a phone. In CI and simulators they report `unavailable` with the procedure below — that is expected, not a failure."},{"type":"paragraph","text":"Register real-device runs in STATUS-HARDWARE.md (Handbook rows) when you complete a procedure on hardware."},{"type":"heading","level":2,"text":"BLE peer"},{"type":"applet","appletId":"ble-peer"},{"type":"heading","level":2,"text":"RNode serial / LoRa"},{"type":"applet","appletId":"rnode-serial"},{"type":"heading","level":2,"text":"Multicast / AutoInterface"},{"type":"applet","appletId":"multicast-auto"},{"type":"heading","level":2,"text":"Camera QR scan"},{"type":"applet","appletId":"camera-qr-scan"}]},{"id":"ref-capabilities","title":"Capabilities","partId":"part-5-reference","partTitle":"Part V — Reference","blocks":[{"type":"heading","level":1,"text":"Capabilities"},{"type":"paragraph","text":"Generated from `CAPABILITY_DEFINITIONS` in `packages/miniapp-runtime`. Every id below must be exercised by at least one Handbook applet (coverage gate)."},{"type":"list","items":["**`identity`** — Use an app-scoped identity for signing and addressing.","**`presence`** — Read coarse peer/interface presence and host info.","**`announce:subscribe`** — Receive announces in the app namespace.","**`announce:publish`** — Publish the app destination.","**`lxmf:send`** — Send LXMF messages from the app destination.","**`lxmf:receive`** — Receive LXMF messages for the app destination.","**`storage:kv`** — Store local key/value data for this app.","**`storage:hyperbee`** — Store ordered local Hyperbee data for this app.","**`resource:fetch`** — Fetch package resources through host budget rules.","**`workspace`** — Read and write project source files in this app's private workspace.","**`ai:chat`** — Send prompts to the host-configured AI service; prompts may include workspace content.","**`apps:package`** — Package and sign apps under this device's publisher identity (asks each time).","**`apps:publish`** — Publish signed apps so other users can find and install them (asks each time).","**`apps:install`** — Ask the host to install apps from a 256t id (asks each time, with capability review).","**`apps:preview`** — Run a built app in the host's sandboxed dev-preview slot.","**`share:cas`** — Store and retrieve bounded content-addressed data shared by 256t id."]},{"type":"paragraph","text":"Manifests declare the full list; users may grant a subset at install. Withholding a capability turns matching probes into `not-granted` cards."},{"type":"paragraph","text":"Tutorial: Capability model. Per-namespace guides: Developing mini-apps."},{"type":"chapter-link","label":"Capability model","chapterId":"sdk-capabilities"},{"type":"chapter-link","label":"Developing mini-apps","chapterId":"sdk-identity"}]},{"id":"ref-widgets","title":"Widget protocol","partId":"part-5-reference","partTitle":"Part V — Reference","blocks":[{"type":"heading","level":1,"text":"Widget protocol"},{"type":"paragraph","text":"Generated from `WIDGET_TYPES` / `WIDGET_PROP_KEYS` in `packages/miniapp-runtime`."},{"type":"paragraph","text":"Hosts render a declarative tree (`ui.render`). Unknown types, props, styles, duplicate ids, or oversized trees are rejected."},{"type":"heading","level":2,"text":"Components"},{"type":"list","items":["**`button`** — props: `event`, `label`","**`code-editor`** — props: `documentId`, `event`, `language`, `readOnly`","**`divider`** — props: none","**`image`** — props: `alt`, `asset`","**`list`** — props: `event`, `items`","**`progress`** — props: `max`, `value`","**`qr-code`** — props: `caption`, `size`, `value`","**`scroll`** — props: `event`","**`spacer`** — props: `size`","**`switch`** — props: `event`, `value`","**`text`** — props: `value`","**`text-input`** — props: `event`, `placeholder`, `value`","**`view`** — props: `accessibilityLabel`"]},{"type":"heading","level":2,"text":"Styles"},{"type":"list","items":["`alignItems`","`backgroundColor`","`color`","`display`","`flexDirection`","`fontSize`","`fontWeight`","`gap`","`height`","`justifyContent`","`margin`","`padding`","`width`"]},{"type":"heading","level":2,"text":"Limits"},{"type":"list","items":["Widget tree JSON budget: 256 KiB (default validator)","`code-editor` languages: javascript, json, text","`qr-code` value: up to 512 characters (94-char 256t ids fit)"]},{"type":"paragraph","text":"Live gallery: Widget gallery."},{"type":"chapter-link","label":"Widget gallery","chapterId":"sdk-widget-gallery"}]},{"id":"ref-host-api","title":"Host API","partId":"part-5-reference","partTitle":"Part V — Reference","blocks":[{"type":"heading","level":1,"text":"Host API"},{"type":"paragraph","text":"Current `HOST_API_VERSION`: **`0.4.0`**. Manifests pin `minHostApi`; hosts reject packages that require a newer API."},{"type":"heading","level":2,"text":"Changelog"},{"type":"list","items":["**`0.1.0`** — Initial mini-app host API: capabilities, broker, lifecycle, widget tree UI, and SDK v1 namespaces.","**`0.2.0`** — Dev-environment capabilities (workspace, ai:chat, apps:*, share:cas), host confirmation channel, dynamic resource limits, pre-launch capability review, code-editor and qr-code widgets.","**`0.3.0`** — host.info() — platform id, host version, HOST_API_VERSION, enabled roles, interface types, and quota snapshot for Handbook diagnostics.","**`0.4.0`** — host.info() includes grantedCapabilities for the calling mini-app (Handbook grant intro and diagnostics)."]},{"type":"heading","level":2,"text":"host.info()"},{"type":"paragraph","text":"Returns platform id, host version, API version, roles, interface types, and quota snapshot — used by the live difference matrix."},{"type":"chapter-link","label":"live difference matrix","chapterId":"difference-matrix"},{"type":"heading","level":2,"text":"Workspace quotas"},{"type":"list","items":["262144 bytes/file","4194304 bytes total per app","512 files per app"]}]},{"id":"ref-packages","title":"Package format","partId":"part-5-reference","partTitle":"Part V — Reference","blocks":[{"type":"heading","level":1,"text":"Package format"},{"type":"paragraph","text":"Mini-apps ship as deterministic **`.tpkg`** archives:"},{"type":"list","items":["Signed manifest (name, version, entry, capabilities, publisher key, `minHostApi`)","Entry bundle (`bundle.js`) and assets","Ed25519 signature over the manifest hash"]},{"type":"paragraph","text":"Packaging flow: Packaging & preview. 256t distribution: docs/256t-distribution.md."},{"type":"chapter-link","label":"Packaging & preview","chapterId":"sdk-apps-package"}]},{"id":"ref-interfaces","title":"Network interfaces","partId":"part-5-reference","partTitle":"Part V — Reference","blocks":[{"type":"heading","level":1,"text":"Network interfaces"},{"type":"paragraph","text":"Reticulum peers attach through typed **PacketInterface** implementations. The live difference matrix lists which types `host.info()` reports for **this** host."},{"type":"chapter-link","label":"live difference matrix","chapterId":"difference-matrix"},{"type":"heading","level":2,"text":"WebSocket (browser gateway)"},{"type":"list","items":["**Leaf client** — browser tab or CI harness dials `ws://` / `wss://` on a gateway.","**Gateway** — desktop host or `tp node --ws-listen [host:]port`.","**Framing** — one Reticulum wire packet per binary WebSocket message.","**Auth** — optional shared token (`--ws-token`)."]},{"type":"paragraph","text":"Full spec: docs/websocket-interface.md. Web host chapter: Web host."},{"type":"chapter-link","label":"Web host","chapterId":"host-web"},{"type":"heading","level":2,"text":"TCP / AutoInterface / Bonjour"},{"type":"paragraph","text":"Desktop and mobile worklets enable TCP client mode, LAN multicast (AutoInterface), and Bonjour discovery when the platform permits. iOS multicast requires the networking multicast entitlement; web hosts omit these entirely."},{"type":"heading","level":2,"text":"BLE phone pipe"},{"type":"paragraph","text":"Android and iOS expose a BLE GATT byte stream for peer links. Web Bluetooth is central-only and not used for the phone-pipe role. Device-gated Handbook probes: Device-gated probes."},{"type":"chapter-link","label":"Device-gated probes","chapterId":"device-gated-probes"},{"type":"heading","level":2,"text":"RNode serial"},{"type":"paragraph","text":"USB serial on desktop/Android; BLE-only on iOS. WebSerial (Chromium) is optional. LoRa bandwidth budgets apply — see LIMITATIONS.md §6."}]},{"id":"ref-quotas","title":"Quotas & limits","partId":"part-5-reference","partTitle":"Part V — Reference","blocks":[{"type":"heading","level":1,"text":"Quotas & limits"},{"type":"paragraph","text":"Generated from `DEFAULT_QUOTAS` (`host-core`) and miniapp-runtime defaults. `host.info()` includes a quota snapshot for diagnostics."},{"type":"heading","level":2,"text":"Host node quotas (desktop / `tp node`)"},{"type":"list","items":["Seed storage: 2147483648 bytes","Propagation store: 268435456 bytes","Propagation messages: 10000","Bandwidth cap: 524288 bytes/s"]},{"type":"paragraph","text":"Override in `<data-dir>/config.json` — see Host configuration."},{"type":"chapter-link","label":"Host configuration","chapterId":"ref-host-config"},{"type":"heading","level":2,"text":"Mini-app workspace (`workspace` capability)"},{"type":"list","items":["262144 bytes per file","4194304 bytes total per app","512 files per app"]},{"type":"heading","level":2,"text":"Widget & AI limits"},{"type":"list","items":["Widget tree JSON: 256 KiB (default validator)","AI chat: 64 messages, 8192 max tokens cap"]},{"type":"heading","level":2,"text":"Transport budgets"},{"type":"paragraph","text":"BLE install budgets (~180 KiB at measured rates) and Resource fetch caps are enforced per link type. See Resource fetch and `conformance/budgets/measured.json`."},{"type":"chapter-link","label":"Resource fetch","chapterId":"sdk-resource-fetch"}]},{"id":"ref-host-config","title":"Host configuration","partId":"part-5-reference","partTitle":"Part V — Reference","blocks":[{"type":"heading","level":1,"text":"Host configuration"},{"type":"paragraph","text":"Generated from `defaultHostConfig()` defaults in `packages/host-core`. Desktop and `tp node` persist overrides in `<data-dir>/config.json`."},{"type":"heading","level":2,"text":"Data directory"},{"type":"list","items":["Default (this platform): `/Users/curt/Library/Application Support/TwistedPear/host`","Identity: `<data-dir>/identity`","Config: `<data-dir>/config.json`"]},{"type":"paragraph","text":"Platform paths: Desktop host. Headless flags: CLI commands."},{"type":"chapter-link","label":"Desktop host","chapterId":"host-desktop"},{"type":"chapter-link","label":"CLI commands","chapterId":"ref-cli"},{"type":"heading","level":2,"text":"Roles (desktop defaults)"},{"type":"list","items":["Transport node: true","Seeder / LAN mirror: true","Propagation server: false","Attach to external rnsd: off"]},{"type":"paragraph","text":"Web hosts force leaf roles — see Web host."},{"type":"chapter-link","label":"Web host","chapterId":"host-web"},{"type":"heading","level":2,"text":"Interfaces (desktop defaults)"},{"type":"list","items":["TCP client: off (target 127.0.0.1:4242)","WebSocket gateway: off (listen 127.0.0.1:9480)","AutoInterface multicast: true","Bonjour discovery: true","I2P SAM: false","RNode serial: false"]},{"type":"paragraph","text":"Interface behavior: Network interfaces."},{"type":"chapter-link","label":"Network interfaces","chapterId":"ref-interfaces"},{"type":"heading","level":2,"text":"Quotas"},{"type":"paragraph","text":"Seed storage, propagation store, message count, and bandwidth caps match Quotas & limits. Override under the `quotas` key."},{"type":"chapter-link","label":"Quotas & limits","chapterId":"ref-quotas"},{"type":"heading","level":2,"text":"AI endpoint"},{"type":"paragraph","text":"`ai` is `null` until configured (desktop **Settings → AI** or `config.json`). Mini-apps use `ai:chat` through the host proxy — see AI chat."},{"type":"chapter-link","label":"AI chat","chapterId":"sdk-ai-chat"},{"type":"heading","level":2,"text":"Status endpoint"},{"type":"paragraph","text":"Opt-in JSON at `http://127.0.0.1:9473/status` when `statusEndpoint: true` or `tp node --status-endpoint`."}]},{"id":"ref-cli","title":"CLI commands","partId":"part-5-reference","partTitle":"Part V — Reference","blocks":[{"type":"heading","level":1,"text":"CLI commands"},{"type":"paragraph","text":"The `tp` CLI scaffolds, packs, publishes, and runs headless peers. Publisher identity comes from `tp init` (Reticulum keypair in the project or data dir)."},{"type":"heading","level":2,"text":"Project workflow"},{"type":"list","items":["`tp init [--force]` — create or load publisher identity","`tp create <hello|chat-min> [app-dir]` — scaffold a mini-app template","`tp dev <app-dir> [--host host:port]` — build and side-load to a dev-mode host","`tp pack <app-dir> [--out file.tpkg]` — build unsigned `.tpkg` archive","`tp sign <file.tpkg>` — re-sign an existing package","`tp publish <app-dir>` — pack, sign, publish to Hyperdrive","`tp update <app-dir> --version <semver>` — bump version and republish"]},{"type":"heading","level":2,"text":"Headless hosts"},{"type":"list","items":["`tp node` — transport/seeder/propagation peer (`--ws-listen`, `--serve-web`, …)","`tp seed` — headless Hyperdrive seeder (`--transport`, `--state-dir`)"]},{"type":"heading","level":2,"text":"Trust"},{"type":"list","items":["`tp trust list|show|add|remove` — manage trusted publisher keys"]},{"type":"paragraph","text":"Handbook packaging in CI: `npm run build:handbook` then `tp pack` in a temp dir. Tutorial: Packaging & preview."},{"type":"chapter-link","label":"Packaging & preview","chapterId":"sdk-apps-package"}]}],"applets":[{"id":"ai-chat","title":"AI chat (host-mediated)","group":"runtime","executionModes":["inline"],"preview":null,"capabilities":["ai:chat"],"surfaces":["ai.chat"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/ai-chat/main.js"},{"id":"announce-loop","title":"Announce publish/subscribe","group":"distribution","executionModes":["inline"],"preview":null,"capabilities":["announce:publish","announce:subscribe"],"surfaces":["announce.publish","announce.subscribe"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/announce-loop/main.js"},{"id":"apps-package-preview","title":"Package + preview (confirmed)","group":"runtime","executionModes":["inline","preview"],"preview":{"project":"handbook-probe-app","manifest":{"name":"hb-probe","version":"0.0.1","entry":"bundle.js","capabilities":["identity"]},"grants":["identity"],"files":{"app.json":"{\"name\":\"hb-probe\",\"version\":\"0.0.1\",\"entry\":\"bundle.js\",\"capabilities\":[\"identity\"]}","bundle.js":"import { ui } from \"@twistedpear/miniapp-sdk\";\nawait ui.render({ root: { id: \"root\", type: \"text\", props: { value: \"Handbook preview probe\" } } });\n"}},"capabilities":["apps:package","apps:preview","workspace"],"surfaces":["apps.packageProject","apps.preview","apps.stopPreview","workspace.write"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/apps-package-preview/main.js"},{"id":"apps-publish-install","title":"Publish + install (confirmed)","group":"distribution","executionModes":["inline"],"preview":null,"capabilities":["apps:publish","apps:install","apps:package","workspace"],"surfaces":["apps.packageProject","apps.publish","apps.install"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/apps-publish-install/main.js"},{"id":"ble-peer","title":"BLE peer visibility","group":"interfaces","executionModes":["inline"],"preview":null,"capabilities":["presence"],"surfaces":["host.info","presence.snapshot"],"expectations":{"android":"device-gated","ios":"device-gated","desktop":"device-gated","web":"unavailable","node":"unavailable"},"sourcePath":"applets/ble-peer/main.js"},{"id":"camera-qr-scan","title":"Camera QR scan","group":"interfaces","executionModes":["inline"],"preview":null,"capabilities":["presence"],"surfaces":["host.info"],"expectations":{"android":"device-gated","ios":"device-gated","desktop":"unavailable","web":"unavailable","node":"unavailable"},"sourcePath":"applets/camera-qr-scan/main.js"},{"id":"host-info","title":"Host info probe","group":"interfaces","executionModes":["inline"],"preview":null,"capabilities":["presence"],"surfaces":["host.info"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/host-info/main.js"},{"id":"identity-hash","title":"App destination hash","group":"crypto","executionModes":["inline"],"preview":null,"capabilities":["identity"],"surfaces":["identity.destinationHash"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/identity-hash/main.js"},{"id":"lxmf-roundtrip","title":"LXMF self-message","group":"crypto","executionModes":["inline"],"preview":null,"capabilities":["identity","lxmf:send","lxmf:receive"],"surfaces":["identity.destinationHash","lxmf.send","lxmf.receive"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/lxmf-roundtrip/main.js"},{"id":"multicast-auto","title":"Multicast / AutoInterface","group":"interfaces","executionModes":["inline"],"preview":null,"capabilities":["presence"],"surfaces":["host.info","presence.snapshot"],"expectations":{"android":"device-gated","ios":"device-gated","desktop":"device-gated","web":"unavailable","node":"unavailable"},"sourcePath":"applets/multicast-auto/main.js"},{"id":"presence-snapshot","title":"Presence snapshot","group":"interfaces","executionModes":["inline"],"preview":null,"capabilities":["presence"],"surfaces":["presence.snapshot"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/presence-snapshot/main.js"},{"id":"resource-fetch","title":"Resource fetch with budget","group":"distribution","executionModes":["inline"],"preview":null,"capabilities":["resource:fetch"],"surfaces":["resource.fetch"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/resource-fetch/main.js"},{"id":"rnode-serial","title":"RNode serial / LoRa path","group":"interfaces","executionModes":["inline"],"preview":null,"capabilities":["presence"],"surfaces":["host.info","presence.snapshot"],"expectations":{"android":"device-gated","ios":"device-gated","desktop":"device-gated","web":"device-gated","node":"unavailable"},"sourcePath":"applets/rnode-serial/main.js"},{"id":"share-cas","title":"CAS share put/get","group":"distribution","executionModes":["inline"],"preview":null,"capabilities":["share:cas"],"surfaces":["share.put","share.get"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/share-cas/main.js"},{"id":"storage-hyperbee","title":"Hyperbee round-trip","group":"storage","executionModes":["inline"],"preview":null,"capabilities":["storage:hyperbee"],"surfaces":["storage.bee.open","storage.bee.put","storage.bee.get","storage.bee.list","storage.bee.del"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/storage-hyperbee/main.js"},{"id":"storage-kv","title":"KV round-trip","group":"storage","executionModes":["inline"],"preview":null,"capabilities":["storage:kv"],"surfaces":["storage.kv.get","storage.kv.set","storage.kv.delete"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/storage-kv/main.js"},{"id":"widget-gallery","title":"Widget gallery smoke","group":"runtime","executionModes":["inline"],"preview":null,"capabilities":["workspace"],"surfaces":["ui.render"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/widget-gallery/main.js"},{"id":"workspace-rw","title":"Workspace read/write","group":"storage","executionModes":["inline"],"preview":null,"capabilities":["workspace"],"surfaces":["workspace.write","workspace.read","workspace.list","workspace.delete"],"expectations":{"android":"pass","ios":"pass","desktop":"pass","web":"pass","node":"pass"},"sourcePath":"applets/workspace-rw/main.js"}],"seeds":[{"path":"applets/ai-chat/applet.json","content":"{\n  \"id\": \"ai-chat\",\n  \"title\": \"AI chat (host-mediated)\",\n  \"group\": \"runtime\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"ai:chat\"\n  ],\n  \"surfaces\": [\n    \"ai.chat\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/ai-chat/main.js","content":"/**\n * Handbook applet: ai.chat against the host-configured endpoint.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  try {\n    const response = await sdk.ai.chat({\n      messages: [{ role: \"user\", content: \"Reply with the single word: handbook\" }]\n    });\n    if (response === null || typeof response !== \"object\" || response.message === undefined) {\n      report({\n        status: \"fail\",\n        details: `Expected AI response object, got: ${JSON.stringify(response)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const content = response.message?.content;\n    if (typeof content !== \"string\" || content.length === 0) {\n      report({\n        status: \"fail\",\n        details: \"AI response message.content was empty\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `AI replied (${response.model ?? \"unknown model\"}): ${content.slice(0, 80)}`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /not configured|UNCONFIGURED|AI_UNCONFIGURED|unavailable/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/announce-loop/applet.json","content":"{\n  \"id\": \"announce-loop\",\n  \"title\": \"Announce publish/subscribe\",\n  \"group\": \"distribution\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"announce:publish\",\n    \"announce:subscribe\"\n  ],\n  \"surfaces\": [\n    \"announce.publish\",\n    \"announce.subscribe\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/announce-loop/main.js","content":"/**\n * Handbook applet: announce.publish then announce.subscribe in a local namespace.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const namespace = \"handbook-probe\";\n  const payload = new TextEncoder().encode(`announce-${started}`);\n  try {\n    await sdk.announce.publish(payload, namespace);\n    const events = await sdk.announce.subscribe(namespace);\n    if (!Array.isArray(events)) {\n      report({\n        status: \"fail\",\n        details: `Expected announce array, got: ${typeof events}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    if (events.length === 0) {\n      report({\n        status: \"fail\",\n        details: \"Subscribe returned no announces after publish\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `Published and observed ${events.length} announce(s) in ${namespace}`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/apps-package-preview/applet.json","content":"{\n  \"id\": \"apps-package-preview\",\n  \"title\": \"Package + preview (confirmed)\",\n  \"group\": \"runtime\",\n  \"executionModes\": [\n    \"inline\",\n    \"preview\"\n  ],\n  \"preview\": {\n    \"project\": \"handbook-probe-app\",\n    \"manifest\": {\n      \"name\": \"hb-probe\",\n      \"version\": \"0.0.1\",\n      \"entry\": \"bundle.js\",\n      \"capabilities\": [\n        \"identity\"\n      ]\n    },\n    \"grants\": [\n      \"identity\"\n    ],\n    \"files\": {\n      \"app.json\": \"{\\\"name\\\":\\\"hb-probe\\\",\\\"version\\\":\\\"0.0.1\\\",\\\"entry\\\":\\\"bundle.js\\\",\\\"capabilities\\\":[\\\"identity\\\"]}\",\n      \"bundle.js\": \"import { ui } from \\\"@twistedpear/miniapp-sdk\\\";\\nawait ui.render({ root: { id: \\\"root\\\", type: \\\"text\\\", props: { value: \\\"Handbook preview probe\\\" } } });\\n\"\n    }\n  },\n  \"capabilities\": [\n    \"apps:package\",\n    \"apps:preview\",\n    \"workspace\"\n  ],\n  \"surfaces\": [\n    \"apps.packageProject\",\n    \"apps.preview\",\n    \"apps.stopPreview\",\n    \"workspace.write\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/apps-package-preview/main.js","content":"/**\n * Handbook applet: seed a tiny project, package it, then preview (host confirmation).\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const project = \"handbook-probe-app\";\n  const manifest = {\n    name: \"hb-probe\",\n    version: \"0.0.1\",\n    entry: \"bundle.js\",\n    capabilities: [\"identity\"]\n  };\n  try {\n    await sdk.workspace.write(\n      `${project}/app.json`,\n      JSON.stringify({ name: manifest.name, version: manifest.version, entry: manifest.entry, capabilities: manifest.capabilities })\n    );\n    await sdk.workspace.write(\n      `${project}/bundle.js`,\n      `import { ui } from \"@twistedpear/miniapp-sdk\";\\nawait ui.render({ root: { id: \"root\", type: \"text\", props: { value: \"probe\" } } });\\n`\n    );\n\n    const packed = await sdk.apps.packageProject(project, manifest);\n    if (packed === null || typeof packed.t256 !== \"string\" || packed.t256.length !== 94) {\n      report({\n        status: \"fail\",\n        details: `Expected package with 256t id, got: ${JSON.stringify(packed)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const preview = await sdk.apps.preview(project, manifest, [\"identity\"]);\n    if (preview === null || preview.launched !== true) {\n      report({\n        status: \"fail\",\n        details: `Expected preview.launched === true, got: ${JSON.stringify(preview)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    await sdk.apps.stopPreview();\n\n    report({\n      status: \"pass\",\n      details: `Packaged (${packed.t256.slice(0, 12)}…) and previewed`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /not configured|UNCONFIGURED|CONFIRMATION_UNAVAILABLE|unavailable/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/apps-publish-install/applet.json","content":"{\n  \"id\": \"apps-publish-install\",\n  \"title\": \"Publish + install (confirmed)\",\n  \"group\": \"distribution\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"apps:publish\",\n    \"apps:install\",\n    \"apps:package\",\n    \"workspace\"\n  ],\n  \"surfaces\": [\n    \"apps.packageProject\",\n    \"apps.publish\",\n    \"apps.install\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/apps-publish-install/main.js","content":"/**\n * Handbook applet: package → publish → install (each step host-confirmed).\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const project = \"handbook-distrib-app\";\n  const manifest = {\n    name: \"hb-distrib\",\n    version: \"0.0.1\",\n    entry: \"bundle.js\",\n    capabilities: [\"identity\"]\n  };\n  try {\n    await sdk.workspace.write(\n      `${project}/app.json`,\n      JSON.stringify({\n        name: manifest.name,\n        version: manifest.version,\n        entry: manifest.entry,\n        capabilities: manifest.capabilities\n      })\n    );\n    await sdk.workspace.write(\n      `${project}/bundle.js`,\n      `import { ui } from \"@twistedpear/miniapp-sdk\";\\nawait ui.render({ root: { id: \"root\", type: \"text\", props: { value: \"distrib\" } } });\\n`\n    );\n\n    const packed = await sdk.apps.packageProject(project, manifest);\n    if (typeof packed?.t256 !== \"string\" || packed.t256.length !== 94) {\n      report({\n        status: \"fail\",\n        details: `Package failed: ${JSON.stringify(packed)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const published = await sdk.apps.publish(packed.t256);\n    if (published === null || typeof published.t256 !== \"string\") {\n      report({\n        status: \"fail\",\n        details: `Publish failed: ${JSON.stringify(published)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const installed = await sdk.apps.install(published.t256);\n    if (installed === null || typeof installed.appId !== \"string\") {\n      report({\n        status: \"fail\",\n        details: `Install failed: ${JSON.stringify(installed)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `Published and installed ${installed.appId}@${installed.version}`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /not configured|UNCONFIGURED|CONFIRMATION_UNAVAILABLE|unavailable/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/ble-peer/applet.json","content":"{\n  \"id\": \"ble-peer\",\n  \"title\": \"BLE peer visibility\",\n  \"group\": \"interfaces\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"presence\"\n  ],\n  \"surfaces\": [\n    \"host.info\",\n    \"presence.snapshot\"\n  ],\n  \"expectations\": {\n    \"android\": \"device-gated\",\n    \"ios\": \"device-gated\",\n    \"desktop\": \"device-gated\",\n    \"web\": \"unavailable\",\n    \"node\": \"unavailable\"\n  }\n}\n"},{"path":"applets/ble-peer/main.js","content":"/**\n * Handbook applet: BLE peer visibility (device-gated).\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const procedure = [\n    \"1. On both phones, open the host app and enable the BLE interface.\",\n    \"2. Keep both devices in foreground for ~30 s until AutoInterface/BLE discovery runs.\",\n    \"3. Confirm presence shows at least one peer on the preferred BLE path.\",\n    \"4. Re-run this applet — expect pass when a BLE peer is visible.\"\n  ].join(\"\\n\");\n\n  try {\n    const info = await sdk.host.info();\n    const types = info.interfaceTypes ?? [];\n    if (!types.includes(\"ble\")) {\n      report({\n        status: \"unavailable\",\n        details: `BLE interface not listed on ${info.platform}.\\n\\nGuided procedure (real device):\\n${procedure}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const snap = await sdk.presence.snapshot();\n    if ((snap.peers ?? 0) < 1) {\n      report({\n        status: \"unavailable\",\n        details: `BLE interface present but no peer connected (peers=${snap.peers ?? 0}).\\n\\nGuided procedure:\\n${procedure}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `BLE peer visible (peers=${snap.peers}, preferred=${snap.preferredInterface ?? \"none\"})`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/camera-qr-scan/applet.json","content":"{\n  \"id\": \"camera-qr-scan\",\n  \"title\": \"Camera QR scan\",\n  \"group\": \"interfaces\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"presence\"\n  ],\n  \"surfaces\": [\n    \"host.info\"\n  ],\n  \"expectations\": {\n    \"android\": \"device-gated\",\n    \"ios\": \"device-gated\",\n    \"desktop\": \"unavailable\",\n    \"web\": \"unavailable\",\n    \"node\": \"unavailable\"\n  }\n}\n"},{"path":"applets/camera-qr-scan/main.js","content":"/**\n * Handbook applet: camera QR install path (device-gated).\n * Probes host platform — real camera scan is a host UI flow, not an SDK call.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const procedure = [\n    \"1. From another device, export a Handbook diagnostic report or package 256t id (QR on Diagnostics screen).\",\n    \"2. On this phone, open the host installer and choose Scan QR / camera import.\",\n    \"3. Grant camera permission when prompted.\",\n    \"4. Scan the QR — confirm install or compare completes.\",\n    \"5. Re-run this applet after a successful scan to record pass (manual confirmation).\"\n  ].join(\"\\n\");\n\n  try {\n    const info = await sdk.host.info();\n    const mobile = info.platform === \"android\" || info.platform === \"ios\";\n    if (!mobile) {\n      report({\n        status: \"unavailable\",\n        details: `Camera QR install is a mobile host flow (${info.platform} has no camera installer path).\\n\\nGuided procedure:\\n${procedure}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"unavailable\",\n      details: `Camera QR scan requires a physical device and user action — not exercisable headlessly.\\n\\nGuided procedure:\\n${procedure}`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/host-info/applet.json","content":"{\n  \"id\": \"host-info\",\n  \"title\": \"Host info probe\",\n  \"group\": \"interfaces\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"presence\"\n  ],\n  \"surfaces\": [\n    \"host.info\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/host-info/main.js","content":"/**\n * Handbook applet: host.info() platform / roles / interfaces / quotas.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  try {\n    if (sdk.host === undefined || typeof sdk.host.info !== \"function\") {\n      report({\n        status: \"unavailable\",\n        details: \"host.info is not available in this sandbox (upgrade host API).\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const info = await sdk.host.info();\n    if (info === null || typeof info !== \"object\") {\n      report({\n        status: \"fail\",\n        details: `Expected a host info object, got: ${String(info)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const platform = typeof info.platform === \"string\" ? info.platform : \"?\";\n    const api = typeof info.hostApiVersion === \"string\" ? info.hostApiVersion : \"?\";\n    const roles = info.roles ?? {};\n    const interfaces = Array.isArray(info.interfaceTypes) ? info.interfaceTypes.join(\",\") : \"\";\n    const grants = Array.isArray(info.grantedCapabilities) ? info.grantedCapabilities.length : 0;\n\n    report({\n      status: \"pass\",\n      details: `platform=${platform} api=${api} grants=${grants} transport=${roles.transport === true} seeder=${roles.seeder === true} interfaces=[${interfaces}]`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /UNKNOWN_METHOD|not available|upgrade host/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/identity-hash/applet.json","content":"{\n  \"id\": \"identity-hash\",\n  \"title\": \"App destination hash\",\n  \"group\": \"crypto\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"identity\"\n  ],\n  \"surfaces\": [\n    \"identity.destinationHash\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/identity-hash/main.js","content":"/**\n * Handbook applet: prove identity.destinationHash() on this host.\n * Export async function run(sdk, report).\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  try {\n    const hash = await sdk.identity.destinationHash();\n    if (typeof hash !== \"string\" || hash.length === 0) {\n      report({\n        status: \"fail\",\n        details: `Expected a non-empty destination hash string, got: ${String(hash)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `destinationHash = ${hash}`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted =\n      message.includes(\"CAPABILITY_DENIED\") ||\n      message.includes(\"has not been granted\") ||\n      message.includes(\"Capability\");\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/lxmf-roundtrip/applet.json","content":"{\n  \"id\": \"lxmf-roundtrip\",\n  \"title\": \"LXMF self-message\",\n  \"group\": \"crypto\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"identity\",\n    \"lxmf:send\",\n    \"lxmf:receive\"\n  ],\n  \"surfaces\": [\n    \"identity.destinationHash\",\n    \"lxmf.send\",\n    \"lxmf.receive\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/lxmf-roundtrip/main.js","content":"/**\n * Handbook applet: send an LXMF message to this app (by app id) and read it back.\n * The default host LXMF backend keys inboxes by app id (same as the chat example).\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  try {\n    const me = await sdk.identity.destinationHash();\n    const body = `handbook-lxmf-${started}`;\n    // Deliver to this Handbook app's inbox (app id === \"handbook\").\n    await sdk.lxmf.send({ to: \"handbook\", subject: \"handbook-probe\", body });\n    const inbox = await sdk.lxmf.receive();\n    if (!Array.isArray(inbox)) {\n      report({\n        status: \"fail\",\n        details: `Expected inbox array, got: ${typeof inbox}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const hit = inbox.find((message) => message && message.body === body);\n    if (hit === undefined) {\n      report({\n        status: \"fail\",\n        details: `Inbox had ${inbox.length} message(s); self-message not found`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `Self-message round-trip (destinationHash=${me})`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/multicast-auto/applet.json","content":"{\n  \"id\": \"multicast-auto\",\n  \"title\": \"Multicast / AutoInterface\",\n  \"group\": \"interfaces\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"presence\"\n  ],\n  \"surfaces\": [\n    \"host.info\",\n    \"presence.snapshot\"\n  ],\n  \"expectations\": {\n    \"android\": \"device-gated\",\n    \"ios\": \"device-gated\",\n    \"desktop\": \"device-gated\",\n    \"web\": \"unavailable\",\n    \"node\": \"unavailable\"\n  }\n}\n"},{"path":"applets/multicast-auto/main.js","content":"/**\n * Handbook applet: multicast / AutoInterface discovery (device-gated).\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const procedure = [\n    \"1. Put two hosts on the same Wi‑Fi LAN (phone + desktop, or two phones).\",\n    \"2. Enable AutoInterface / multicast discovery in each host app.\",\n    \"3. Wait for announces — presence should show peers without manual TCP config.\",\n    \"4. Re-run this applet — expect pass when auto peers are visible.\"\n  ].join(\"\\n\");\n\n  try {\n    const info = await sdk.host.info();\n    const types = info.interfaceTypes ?? [];\n    if (!types.includes(\"auto\")) {\n      report({\n        status: \"unavailable\",\n        details: `AutoInterface not listed on ${info.platform} (types: ${types.join(\", \") || \"none\"}).\\n\\nGuided procedure (LAN + hardware):\\n${procedure}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const snap = await sdk.presence.snapshot();\n    if ((snap.peers ?? 0) < 1) {\n      report({\n        status: \"unavailable\",\n        details: `AutoInterface present but no LAN peer yet (peers=${snap.peers ?? 0}).\\n\\nGuided procedure:\\n${procedure}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `AutoInterface peer visible (peers=${snap.peers}, preferred=${snap.preferredInterface ?? \"none\"})`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/presence-snapshot/applet.json","content":"{\n  \"id\": \"presence-snapshot\",\n  \"title\": \"Presence snapshot\",\n  \"group\": \"interfaces\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"presence\"\n  ],\n  \"surfaces\": [\n    \"presence.snapshot\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/presence-snapshot/main.js","content":"/**\n * Handbook applet: presence.snapshot() on this host.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  try {\n    const snap = await sdk.presence.snapshot();\n    if (snap === null || typeof snap !== \"object\") {\n      report({\n        status: \"fail\",\n        details: `Expected a presence snapshot object, got: ${String(snap)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `peers=${snap.peers} interfaces=${snap.onlineInterfaces} preferred=${snap.preferredInterface ?? \"none\"}`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/resource-fetch/applet.json","content":"{\n  \"id\": \"resource-fetch\",\n  \"title\": \"Resource fetch with budget\",\n  \"group\": \"distribution\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"resource:fetch\"\n  ],\n  \"surfaces\": [\n    \"resource.fetch\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/resource-fetch/main.js","content":"/**\n * Handbook applet: resource.fetch under a host budget.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  try {\n    const bytes = await sdk.resource.fetch({\n      resourceId: \"handbook:probe\",\n      budgetBytes: 4096\n    });\n    if (!(bytes instanceof Uint8Array) || bytes.length === 0) {\n      report({\n        status: \"fail\",\n        details: `Expected non-empty Uint8Array, got: ${typeof bytes}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `Fetched ${bytes.length} byte(s) for handbook:probe`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /not configured|UNCONFIGURED|unavailable|not found/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/rnode-serial/applet.json","content":"{\n  \"id\": \"rnode-serial\",\n  \"title\": \"RNode serial / LoRa path\",\n  \"group\": \"interfaces\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"presence\"\n  ],\n  \"surfaces\": [\n    \"host.info\",\n    \"presence.snapshot\"\n  ],\n  \"expectations\": {\n    \"android\": \"device-gated\",\n    \"ios\": \"device-gated\",\n    \"desktop\": \"device-gated\",\n    \"web\": \"device-gated\",\n    \"node\": \"unavailable\"\n  }\n}\n"},{"path":"applets/rnode-serial/main.js","content":"/**\n * Handbook applet: RNode serial / LoRa interface (device-gated).\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const procedure = [\n    \"1. Connect an RNode over USB (desktop/Android) or BLE (iOS) per host docs.\",\n    \"2. Enable the RNode interface in the host app.\",\n    \"3. Confirm host.info lists `rnode` and the interface reports online.\",\n    \"4. Optional: exchange a small LXMF message with a peer over LoRa.\",\n    \"5. Re-run this applet — expect pass when the RNode path is online.\"\n  ].join(\"\\n\");\n\n  try {\n    const info = await sdk.host.info();\n    const types = info.interfaceTypes ?? [];\n    if (!types.includes(\"rnode\")) {\n      report({\n        status: \"unavailable\",\n        details: `RNode interface not listed on ${info.platform}.\\n\\nGuided procedure (hardware):\\n${procedure}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const snap = await sdk.presence.snapshot();\n    if ((snap.onlineInterfaces ?? 0) < 1) {\n      report({\n        status: \"unavailable\",\n        details: `RNode interface declared but no online interfaces (online=${snap.onlineInterfaces ?? 0}).\\n\\nGuided procedure:\\n${procedure}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `RNode path online (interfaces=${snap.onlineInterfaces}, peers=${snap.peers ?? 0})`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/share-cas/applet.json","content":"{\n  \"id\": \"share-cas\",\n  \"title\": \"CAS share put/get\",\n  \"group\": \"distribution\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"share:cas\"\n  ],\n  \"surfaces\": [\n    \"share.put\",\n    \"share.get\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/share-cas/main.js","content":"/**\n * Handbook applet: share.put → share.get round-trip.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const content = `handbook-cas-${started}`;\n  try {\n    const put = await sdk.share.put(content);\n    if (put === null || typeof put !== \"object\" || typeof put.t256 !== \"string\") {\n      report({\n        status: \"fail\",\n        details: `Expected { t256 }, got: ${JSON.stringify(put)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    if (put.t256.length !== 94) {\n      report({\n        status: \"fail\",\n        details: `Expected 94-char 256t id, got length ${put.t256.length}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const got = await sdk.share.get(put.t256);\n    if (got !== content) {\n      report({\n        status: \"fail\",\n        details: `CAS get mismatch: ${String(got)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: `CAS round-trip (${put.t256.slice(0, 12)}…)`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /not configured|UNCONFIGURED|unavailable/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/storage-hyperbee/applet.json","content":"{\n  \"id\": \"storage-hyperbee\",\n  \"title\": \"Hyperbee round-trip\",\n  \"group\": \"storage\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"storage:hyperbee\"\n  ],\n  \"surfaces\": [\n    \"storage.bee.open\",\n    \"storage.bee.put\",\n    \"storage.bee.get\",\n    \"storage.bee.list\",\n    \"storage.bee.del\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/storage-hyperbee/main.js","content":"/**\n * Handbook applet: storage.bee open → put → get → list → del.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const key = `handbook:bee:${started}`;\n  const payload = new TextEncoder().encode(`bee-${started}`);\n  try {\n    await sdk.storage.bee.open();\n    await sdk.storage.bee.put(key, payload);\n    const got = await sdk.storage.bee.get(key);\n    if (got === null) {\n      report({\n        status: \"fail\",\n        details: \"Hyperbee get returned null after put\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    if (new TextDecoder().decode(got) !== `bee-${started}`) {\n      report({\n        status: \"fail\",\n        details: \"Hyperbee value mismatch\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const listed = await sdk.storage.bee.list({ gte: key, limit: 5 });\n    if (!Array.isArray(listed) || listed.length === 0) {\n      report({\n        status: \"fail\",\n        details: \"Hyperbee list did not include the put key\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    await sdk.storage.bee.del(key);\n    const after = await sdk.storage.bee.get(key);\n    if (after !== null) {\n      report({\n        status: \"fail\",\n        details: \"Hyperbee value still present after del\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: \"Hyperbee open → put → get → list → del succeeded\",\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /not configured|UNCONFIGURED|unavailable/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/storage-kv/applet.json","content":"{\n  \"id\": \"storage-kv\",\n  \"title\": \"KV round-trip\",\n  \"group\": \"storage\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"storage:kv\"\n  ],\n  \"surfaces\": [\n    \"storage.kv.get\",\n    \"storage.kv.set\",\n    \"storage.kv.delete\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/storage-kv/main.js","content":"/**\n * Handbook applet: storage.kv set → get → delete.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const key = \"handbook:applet-kv-probe\";\n  const payload = new TextEncoder().encode(`probe-${started}`);\n  try {\n    await sdk.storage.kv.set(key, payload);\n    const got = await sdk.storage.kv.get(key);\n    if (got === null) {\n      report({\n        status: \"fail\",\n        details: \"KV get returned null after set\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const text = new TextDecoder().decode(got);\n    if (text !== `probe-${started}`) {\n      report({\n        status: \"fail\",\n        details: `KV value mismatch: ${text}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    await sdk.storage.kv.delete(key);\n    const after = await sdk.storage.kv.get(key);\n    if (after !== null) {\n      report({\n        status: \"fail\",\n        details: \"KV value still present after delete\",\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    report({\n      status: \"pass\",\n      details: \"KV set → get → delete succeeded\",\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/widget-gallery/applet.json","content":"{\n  \"id\": \"widget-gallery\",\n  \"title\": \"Widget gallery smoke\",\n  \"group\": \"runtime\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"workspace\"\n  ],\n  \"surfaces\": [\n    \"ui.render\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/widget-gallery/main.js","content":"/**\n * Handbook applet: validate that every widget component type can appear in a tree.\n * Inline mode shares the Handbook sandbox; the runtime re-renders the chapter after.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  try {\n    await sdk.workspace.write(\"probes/widget-gallery.txt\", \"gallery-seed\");\n\n    await sdk.ui.render({\n      root: {\n        id: \"gallery-root\",\n        type: \"scroll\",\n        style: { padding: 8, gap: 6 },\n        children: [\n          {\n            id: \"g-view\",\n            type: \"view\",\n            style: { gap: 4 },\n            children: [\n              { id: \"g-text\", type: \"text\", props: { value: \"Widget gallery\" } },\n              { id: \"g-image\", type: \"image\", props: { asset: \"handbook-icon\", alt: \"icon\" } },\n              { id: \"g-button\", type: \"button\", props: { label: \"Ok\", event: \"hb.gallery.noop\" } },\n              {\n                id: \"g-input\",\n                type: \"text-input\",\n                props: { value: \"\", placeholder: \"type\", event: \"hb.gallery.input\" }\n              },\n              { id: \"g-switch\", type: \"switch\", props: { value: false, event: \"hb.gallery.switch\" } },\n              { id: \"g-progress\", type: \"progress\", props: { value: 0.4 } },\n              { id: \"g-divider\", type: \"divider\" },\n              { id: \"g-spacer\", type: \"spacer\", props: { size: 8 } },\n              { id: \"g-list\", type: \"list\", props: { items: [\"item-a\", \"item-b\"] } },\n              {\n                id: \"g-editor\",\n                type: \"code-editor\",\n                props: { documentId: \"probes/widget-gallery.txt\", language: \"text\", readOnly: true }\n              },\n              {\n                id: \"g-qr\",\n                type: \"qr-code\",\n                props: { value: \"handbook-gallery\", caption: \"gallery\", size: 96 }\n              }\n            ]\n          }\n        ]\n      }\n    });\n\n    report({\n      status: \"pass\",\n      details:\n        \"Rendered scroll/view/text/image/button/text-input/switch/progress/divider/spacer/list/code-editor/qr-code\",\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"applets/workspace-rw/applet.json","content":"{\n  \"id\": \"workspace-rw\",\n  \"title\": \"Workspace read/write\",\n  \"group\": \"storage\",\n  \"executionModes\": [\n    \"inline\"\n  ],\n  \"preview\": null,\n  \"capabilities\": [\n    \"workspace\"\n  ],\n  \"surfaces\": [\n    \"workspace.write\",\n    \"workspace.read\",\n    \"workspace.list\",\n    \"workspace.delete\"\n  ],\n  \"expectations\": {\n    \"android\": \"pass\",\n    \"ios\": \"pass\",\n    \"desktop\": \"pass\",\n    \"web\": \"pass\",\n    \"node\": \"pass\"\n  }\n}\n"},{"path":"applets/workspace-rw/main.js","content":"/**\n * Handbook applet: workspace write → read → list → remove.\n */\nexport async function run(sdk, report) {\n  const started = Date.now();\n  const path = `probes/workspace-${started}.txt`;\n  const body = `workspace-probe-${started}`;\n  try {\n    await sdk.workspace.write(path, body);\n    const read = await sdk.workspace.read(path);\n    if (read !== body) {\n      report({\n        status: \"fail\",\n        details: `Workspace read mismatch: ${String(read)}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    const listed = await sdk.workspace.list(\"probes/\");\n    if (!Array.isArray(listed) || !listed.some((entry) => entry.path === path || entry === path)) {\n      const paths = Array.isArray(listed)\n        ? listed.map((entry) => (typeof entry === \"string\" ? entry : entry.path)).join(\", \")\n        : String(listed);\n      report({\n        status: \"fail\",\n        details: `Workspace list missing ${path}; got: ${paths}`,\n        timings: { ms: Date.now() - started }\n      });\n      return;\n    }\n\n    await sdk.workspace.remove(path);\n    report({\n      status: \"pass\",\n      details: `Workspace write → read → list → remove for ${path}`,\n      timings: { ms: Date.now() - started }\n    });\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error);\n    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);\n    const unavailable = /not configured|UNCONFIGURED|unavailable/i.test(message);\n    report({\n      status: notGranted ? \"not-granted\" : unavailable ? \"unavailable\" : \"fail\",\n      details: message,\n      timings: { ms: Date.now() - started }\n    });\n  }\n}\n"},{"path":"chapters/concepts-in-practice/source.md","content":"# Concepts in practice\n\nThe applets below run on **this** host — the same probes used in Part III and\nPart IV diagnostics, grouped for readers who want to see Reticulum building\nblocks work before diving into SDK chapters.\n\n## Identity\n\n{{applet:identity-hash}}\n\n## Announce loop\n\n{{applet:announce-loop}}\n\n## LXMF self-message\n\n{{applet:lxmf-roundtrip}}\n\nNext: [Identity & signing](chapter:sdk-identity) · [Running diagnostics](chapter:running-diagnostics)\n"},{"path":"chapters/device-gated-probes/source.md","content":"# Device-gated probes\n\nThese applets need **real hardware or a guided manual step** on a phone. In CI and\nsimulators they report `unavailable` with the procedure below — that is expected, not\na failure.\n\nRegister real-device runs in [STATUS-HARDWARE.md](../../../STATUS-HARDWARE.md) (Handbook\nrows) when you complete a procedure on hardware.\n\n## BLE peer\n\n{{applet:ble-peer}}\n\n## RNode serial / LoRa\n\n{{applet:rnode-serial}}\n\n## Multicast / AutoInterface\n\n{{applet:multicast-auto}}\n\n## Camera QR scan\n\n{{applet:camera-qr-scan}}\n"},{"path":"chapters/difference-matrix/source.md","content":"# Live difference matrix\n\nHosts share one SDK and widget protocol, but platform sandboxes and entitlements\nshape what is actually available. Per-host chapters describe architecture and\nlifecycle; `host.info()` returns the facts for **this** host — platform id, host /\nAPI versions, enabled roles, interface types, and quota snapshot — instead of\nasserting differences in stale prose.\n\n- [Android host](chapter:host-android) · [iOS host](chapter:host-ios) ·\n  [Desktop host](chapter:host-desktop) · [Web host](chapter:host-web) ·\n  [Headless node & seeder](chapter:host-headless)\n\n## Probe\n\n{{applet:host-info}}\n\n## How to read differences\n\n| Signal | Typical cause | See also |\n|---|---|---|\n| `platform=web` + no `auto`/`ble` | Browser leaf: WebSocket gateway only | [Web host](chapter:host-web), [LIMITATIONS.md](../../../LIMITATIONS.md) §8 |\n| `platform=ios` + missing multicast | Multicast entitlement / Bonjour path | [iOS host](chapter:host-ios), LIMITATIONS §6 |\n| `transport=false` on phones | Leaf role; desktops default transport + seeder | [Android](chapter:host-android) / [Desktop](chapter:host-desktop) |\n| Interface listed but offline | Feature present; peer/hardware not connected | Part IV diagnostics |\n| `not-granted` applet cards | User withheld a manifest capability | [Capability model](chapter:sdk-capabilities) |\n| BLE / RNode / camera `device-gated` | Hardware or second device required | [Device-gated probes](chapter:device-gated-probes) |\n| Large install over BLE slow | Bulk plane vs Resource fallback | [Budgets & quotas](chapter:sdk-budgets) |\n\nCross-check with presence (`presence.snapshot`) and Part IV diagnostics: run all\napplets, export a report via `share:cas`, then paste another device's 256t id to\ndiff results side-by-side.\n"},{"path":"chapters/host-android/source.md","content":"# Android host\n\nThe Android host is a React Native shell around the same **Bare worklet** used on\niOS and desktop. Reticulum, LXMF, catalog install, and the mini-app runtime all\nrun in the worklet; the JVM layer supplies lifecycle, BLE, multicast bridges, and\na foreground service so the node can stay reachable in the background.\n\n## Architecture\n\n- **Expo / RN shell** — settings, grants, confirmations, widget renderer.\n- **Bare worklet child** — `reticulum-ts`, `host-core` leaf roles, broker, sandboxes.\n- **Native bridges** — TCP, AutoInterface multicast, Bonjour, BLE central/peripheral,\n  RNode serial-over-BLE, camera (QR install).\n\n## Roles\n\nAndroid phones default to **leaf** peers: transport routing and package seeding are\noff unless the operator enables them on a dedicated device. Most users run a leaf\nthat dials LAN peers or a desktop gateway.\n\n## Lifecycle\n\n- **Foreground** — full interface set, mini-app execution, BLE active.\n- **Background** — `NodeForegroundService` keeps the worklet alive; interfaces\n  quiesce on a grace timer then reconnect on resume (see\n  [LIMITATIONS.md](../../../LIMITATIONS.md) §6).\n- **Suspended** — no mini-app execution; LXMF store-and-forward only.\n\n## Storage\n\nApp data lives under the host's private app storage. Identity keys and package\narchives are worklet-managed; clearing app data resets the peer.\n\n## What to expect on this host\n\nUse the [live difference matrix](chapter:difference-matrix) on a real device or\nemulator — `host.info()` reports `platform=android`, interface types, and roles\nfor **this** install. BLE pair, RNode, multicast, and camera probes are\n[device-gated](chapter:device-gated-probes) in CI.\n"},{"path":"chapters/host-desktop/source.md","content":"# Desktop host\n\nThe desktop host is the **always-on peer** in a typical mesh: transport routing,\npackage seeding, optional LXMF propagation, and a gateway for browser tabs via\nthe WebSocket Reticulum interface.\n\n## Architecture\n\n- **Electron shell** (`apps/host-desktop`) — tray, power events, native multicast/\n  Bonjour bridges, crash supervision, DOM widget renderer.\n- **Bare worklet child** — same stack as mobile; stdio IPC to the shell.\n- **`host-core`** — shared engine with headless `tp node` / `tp seed`.\n\n## Default roles\n\n| Role | Default | Notes |\n|---|---|---|\n| Transport node | on | Off when `--attach-rnsd` leaf mode |\n| Seeder / LAN mirror | on | Quota'd Hyperdrive serving |\n| Propagation server | off | Enable in UI or `--propagation` |\n| WebSocket gateway | off | `--ws-listen` for web-host tabs |\n\n## Lifecycle\n\n- **Suspend** (system sleep) — worklet quiesces interfaces.\n- **Resume** — reconnect and re-announce.\n- **Crash** — supervisor restarts the worklet with exponential backoff.\n\n## First-boot apps\n\nFresh desktop installs seed **handbook**, **devstudio**, and **chat** from the\nTwistedPear platform publisher. Open **Installed** and launch **handbook** — you\nare reading it.\n\n## Config & data\n\nPlatform data directory (identity, `config.json`, quotas):\n\n- macOS: `~/Library/Application Support/TwistedPear/host`\n- Linux: `~/.local/share/twistedpear/host`\n- Windows: `%APPDATA%/TwistedPear/host`\n\nFull schema: [Host configuration](chapter:ref-host-config).\n\nOpt-in status JSON: `http://127.0.0.1:9473/status` when `--status-endpoint` is set.\n\nLive capability view: [Live difference matrix](chapter:difference-matrix).\nDetails: [docs/desktop-host.md](../../../docs/desktop-host.md).\n"},{"path":"chapters/host-headless/sample-0.txt","content":"tp node --data-dir ~/.local/share/twistedpear/host\ntp node --ws-listen 9480 --serve-web\ntp node --attach-rnsd 127.0.0.1:4242 --no-transport\ntp node --propagation --status-endpoint\n"},{"path":"chapters/host-headless/sample-1.txt","content":"tp seed --transport --state-dir .tp/seeder\n"},{"path":"chapters/host-headless/source.md","content":"# Headless node & seeder\n\n`tp node` and `tp seed` run **`host-core`** without a UI — the same engine as the\ndesktop worklet, suitable for servers, CI, and LAN gateways.\n\n## `tp node`\n\nAlways-on desktop-class peer from the CLI:\n\n```bash\ntp node --data-dir ~/.local/share/twistedpear/host\ntp node --ws-listen 9480 --serve-web\ntp node --attach-rnsd 127.0.0.1:4242 --no-transport\ntp node --propagation --status-endpoint\n```\n\nCommon flags:\n\n- `--no-transport` / `--no-seeder` — leaf or attach-only modes\n- `--ws-listen [host:]port` — WebSocket gateway for browser tabs\n- `--ws-token <token>` — optional shared secret on the gateway\n- `--serve-web [dir]` — serve the built web-host bundle from this machine\n- `--status-endpoint` — localhost JSON status on port 9473\n\n## `tp seed`\n\nHeadless package mirror focused on Hyperdrive seeding:\n\n```bash\ntp seed --transport --state-dir .tp/seeder\n```\n\nUse when you want seeding without the Electron shell. Quotas match desktop defaults\n(see [Quotas & limits](chapter:ref-quotas)).\n\n## When to use headless vs desktop\n\n| Need | Headless | Desktop host |\n|---|---|---|\n| WebSocket gateway for web tabs | `tp node --ws-listen` | enable in config / CLI |\n| Tray UI + crash supervision | — | Electron shell |\n| CI / docker interop | `tp node` in containers | optional |\n| Developer mini-app side-load | `tp dev` targets either | `tp dev` |\n\n## Handbook on node\n\nCI runs the Handbook with `npm run test:handbook` — pack, install, render every\nchapter, execute applets on the Node Worker sandbox backend. This is the same\ncatalog desktop seeds, without graphics.\n\nCLI reference: [CLI commands](chapter:ref-cli).\n"},{"path":"chapters/host-ios/source.md","content":"# iOS host\n\nThe iOS host mirrors Android: a React Native shell supervising a **Bare worklet**\nwith the same protocol stack. Platform entitlements and background rules shape\nwhich interfaces stay online when the app is not in the foreground.\n\n## Architecture\n\n- **Expo / RN shell** — peer browser, grants, confirmations, widget renderer.\n- **Bare worklet child** — identical broker and sandbox model to Android/desktop.\n- **Native bridges** — TCP client, Bonjour, BLE (central/peripheral), RNode\n  over BLE only (no USB serial on iOS).\n\n## Lifecycle (no foreground-service equivalent)\n\niOS has no Android-style foreground service. Backgrounding is a **state\ntransition**:\n\n- **Foreground** — interfaces and the active mini-app run normally.\n- **Background grace** — native lifecycle sends `suspend-node`; worklet quiesces\n  TCP/multicast timers; existing BLE links may survive briefly.\n- **Suspended** — no mini-app execution; pending LXMF is persisted for later sync.\n\nStore-posture builds refuse catalog install and dev side-load; development builds\nkeep parity with Android for `tp dev` and Handbook installs.\n\n## Entitlements\n\nLocal network, Bonjour (`_reticulum._udp`), Bluetooth, and multicast require\nusage strings and (for multicast) the networking multicast entitlement. Until\nentitlement filing completes, multicast may report unavailable even though the\ncode path exists — check `host.info()` on **this** device.\n\n## Simulator vs device\n\nThe simulator validates worklet boot, TCP/localhost, store-posture refusal, and\nHandbook software-tier slices. BLE, real background timing, and LAN multicast\nneed hardware — see [Device-gated probes](chapter:device-gated-probes).\n\nCompare live signals: [Live difference matrix](chapter:difference-matrix).\n"},{"path":"chapters/host-web/sample-0.txt","content":"Browser tab (Expo web)\n  host UI + RNW widget renderer\nCore Web Worker — reticulum-ts, host-core leaf, broker\nPer-app sandbox — iframe + Worker, broker-only API\nWebSocketClientInterface ──wss──▶ gateway node\n"},{"path":"chapters/host-web/source.md","content":"# Web host\n\nThe web host is a **browser tab** running the full mini-app stack in-page — not a\nremote UI for another node. `reticulum-ts` executes in a core Web Worker;\nper-app sandboxes use opaque-origin iframes plus workers; the host UI renders\nwidgets with React Native for Web.\n\n## Leaf-only posture\n\nBrowsers cannot accept inbound connections or open raw TCP/UDP. The web host is\npermanently a **leaf peer**:\n\n- No transport-node, seeder, or propagation roles — ever.\n- Reticulum reachability goes through a **WebSocket gateway** on a desktop or\n  `tp node` peer (`--ws-listen`).\n- Bulk installs use the gateway's `/bulk-fetch` proxy; offline fallback is\n  Reticulum Resource transfer.\n\n## Architecture\n\n```\nBrowser tab (Expo web)\n  host UI + RNW widget renderer\nCore Web Worker — reticulum-ts, host-core leaf, broker\nPer-app sandbox — iframe + Worker, broker-only API\nWebSocketClientInterface ──wss──▶ gateway node\n```\n\n## Security notes\n\nIdentity keys live in IndexedDB encrypted with WebCrypto — weaker than a hardware\nkeystore. The **page origin is part of the trust base**: default posture is\nself-serving from your own node (`tp node --serve-web`). See\n[LIMITATIONS.md](../../../LIMITATIONS.md) §8.\n\n## Radios & serial\n\nNo BLE peripheral, no multicast AutoInterface. WebSerial RNode (Chromium) is a\nstretch path; real USB LoRa E2E is device-gated. Probes report `unavailable`\nhonestly on `platform=web`.\n\nGateway spec: [WebSocket interface](chapter:ref-interfaces). Live matrix:\n[Live difference matrix](chapter:difference-matrix).\n"},{"path":"chapters/pears-bulk-plane/source.md","content":"# Pears bulk plane\n\nReticulum is the **control plane** — identity, announces, links, LXMF, and\noff-grid Resource transfer. When IP connectivity exists, large package syncs\nprefer the **Pears bulk plane**: Hypercore, Hyperdrive, and Hyperswarm.\n\n## Why two planes\n\nReticulum links are optimized for constrained carriers (BLE, LoRa) with small\nMTUs and high latency. Shipping a multi-megabyte `.tpkg` over those links works\nbut is slow. Hyperswarm discovery plus Hyperdrive replication uses TCP where\navailable and falls back to Reticulum Resources when it is not.\n\n## Building blocks\n\n- **Hypercore** — append-only signed logs. Each app package is a deterministic\n  archive keyed by the publisher's feed.\n- **Hyperdrive** — a filesystem view over one or more Hypercores. `tp publish`\n  seeds the signed `.tpkg`; peers replicate blocks from seeders on the LAN or\n  DHT.\n- **Hyperswarm** — topic-based peer discovery for Hyperdrive replication. Desktop\n  and headless hosts run seeders by default; phones are usually leaf consumers.\n\n## In practice\n\n| Operation | Typical plane |\n|---|---|\n| Discover an app announce | Reticulum control plane |\n| Install over LAN / internet | Hyperdrive bulk fetch |\n| Install with no IP path | Reticulum Resource transfer |\n| LXMF chat message | Reticulum only |\n| Handbook diagnostic report (`share.put`) | CAS + optional Hyperdrive seed |\n\nHeadless seeding: [Headless node & seeder](chapter:host-headless). Distribution\ntutorial: [Publish & install](chapter:sdk-apps-publish).\n"},{"path":"chapters/ref-capabilities/source.md","content":"# Capabilities\n\nGenerated from `CAPABILITY_DEFINITIONS` in `packages/miniapp-runtime`.\nEvery id below must be exercised by at least one Handbook applet (coverage gate).\n\n- **`identity`** — Use an app-scoped identity for signing and addressing.\n- **`presence`** — Read coarse peer/interface presence and host info.\n- **`announce:subscribe`** — Receive announces in the app namespace.\n- **`announce:publish`** — Publish the app destination.\n- **`lxmf:send`** — Send LXMF messages from the app destination.\n- **`lxmf:receive`** — Receive LXMF messages for the app destination.\n- **`storage:kv`** — Store local key/value data for this app.\n- **`storage:hyperbee`** — Store ordered local Hyperbee data for this app.\n- **`resource:fetch`** — Fetch package resources through host budget rules.\n- **`workspace`** — Read and write project source files in this app's private workspace.\n- **`ai:chat`** — Send prompts to the host-configured AI service; prompts may include workspace content.\n- **`apps:package`** — Package and sign apps under this device's publisher identity (asks each time).\n- **`apps:publish`** — Publish signed apps so other users can find and install them (asks each time).\n- **`apps:install`** — Ask the host to install apps from a 256t id (asks each time, with capability review).\n- **`apps:preview`** — Run a built app in the host's sandboxed dev-preview slot.\n- **`share:cas`** — Store and retrieve bounded content-addressed data shared by 256t id.\n\nManifests declare the full list; users may grant a subset at install.\nWithholding a capability turns matching probes into `not-granted` cards.\n\nTutorial: [Capability model](chapter:sdk-capabilities).\nPer-namespace guides: [Developing mini-apps](chapter:sdk-identity).\n"},{"path":"chapters/ref-cli/source.md","content":"# CLI commands\n\nThe `tp` CLI scaffolds, packs, publishes, and runs headless peers. Publisher\nidentity comes from `tp init` (Reticulum keypair in the project or data dir).\n\n## Project workflow\n\n- `tp init [--force]` — create or load publisher identity\n- `tp create <hello|chat-min> [app-dir]` — scaffold a mini-app template\n- `tp dev <app-dir> [--host host:port]` — build and side-load to a dev-mode host\n- `tp pack <app-dir> [--out file.tpkg]` — build unsigned `.tpkg` archive\n- `tp sign <file.tpkg>` — re-sign an existing package\n- `tp publish <app-dir>` — pack, sign, publish to Hyperdrive\n- `tp update <app-dir> --version <semver>` — bump version and republish\n\n## Headless hosts\n\n- `tp node` — transport/seeder/propagation peer (`--ws-listen`, `--serve-web`, …)\n- `tp seed` — headless Hyperdrive seeder (`--transport`, `--state-dir`)\n\n## Trust\n\n- `tp trust list|show|add|remove` — manage trusted publisher keys\n\nHandbook packaging in CI: `npm run build:handbook` then `tp pack` in a temp dir.\nTutorial: [Packaging & preview](chapter:sdk-apps-package).\n"},{"path":"chapters/ref-host-api/source.md","content":"# Host API\n\nCurrent `HOST_API_VERSION`: **`0.4.0`**.\nManifests pin `minHostApi`; hosts reject packages that require a newer API.\n\n## Changelog\n\n- **`0.1.0`** — Initial mini-app host API: capabilities, broker, lifecycle, widget tree UI, and SDK v1 namespaces.\n- **`0.2.0`** — Dev-environment capabilities (workspace, ai:chat, apps:*, share:cas), host confirmation channel, dynamic resource limits, pre-launch capability review, code-editor and qr-code widgets.\n- **`0.3.0`** — host.info() — platform id, host version, HOST_API_VERSION, enabled roles, interface types, and quota snapshot for Handbook diagnostics.\n- **`0.4.0`** — host.info() includes grantedCapabilities for the calling mini-app (Handbook grant intro and diagnostics).\n\n## host.info()\n\nReturns platform id, host version, API version, roles, interface types, and quota\nsnapshot — used by the [live difference matrix](chapter:difference-matrix).\n\n## Workspace quotas\n\n- 262144 bytes/file\n- 4194304 bytes total per app\n- 512 files per app\n"},{"path":"chapters/ref-host-config/source.md","content":"# Host configuration\n\nGenerated from `defaultHostConfig()` defaults in `packages/host-core`.\nDesktop and `tp node` persist overrides in `<data-dir>/config.json`.\n\n## Data directory\n\n- Default (this platform): `/Users/curt/Library/Application Support/TwistedPear/host`\n- Identity: `<data-dir>/identity`\n- Config: `<data-dir>/config.json`\n\nPlatform paths: [Desktop host](chapter:host-desktop). Headless flags:\n[CLI commands](chapter:ref-cli).\n\n## Roles (desktop defaults)\n\n- Transport node: true\n- Seeder / LAN mirror: true\n- Propagation server: false\n- Attach to external rnsd: off\n\nWeb hosts force leaf roles — see [Web host](chapter:host-web).\n\n## Interfaces (desktop defaults)\n\n- TCP client: off (target 127.0.0.1:4242)\n- WebSocket gateway: off (listen 127.0.0.1:9480)\n- AutoInterface multicast: true\n- Bonjour discovery: true\n- I2P SAM: false\n- RNode serial: false\n\nInterface behavior: [Network interfaces](chapter:ref-interfaces).\n\n## Quotas\n\nSeed storage, propagation store, message count, and bandwidth caps match\n[Quotas & limits](chapter:ref-quotas). Override under the `quotas` key.\n\n## AI endpoint\n\n`ai` is `null` until configured (desktop **Settings → AI** or `config.json`).\nMini-apps use `ai:chat` through the host proxy — see [AI chat](chapter:sdk-ai-chat).\n\n## Status endpoint\n\nOpt-in JSON at `http://127.0.0.1:9473/status` when `statusEndpoint: true`\nor `tp node --status-endpoint`.\n"},{"path":"chapters/ref-interfaces/source.md","content":"# Network interfaces\n\nReticulum peers attach through typed **PacketInterface** implementations.\nThe [live difference matrix](chapter:difference-matrix) lists which types\n`host.info()` reports for **this** host.\n\n## WebSocket (browser gateway)\n\n- **Leaf client** — browser tab or CI harness dials `ws://` / `wss://` on a gateway.\n- **Gateway** — desktop host or `tp node --ws-listen [host:]port`.\n- **Framing** — one Reticulum wire packet per binary WebSocket message.\n- **Auth** — optional shared token (`--ws-token`).\n\nFull spec: [docs/websocket-interface.md](../../../docs/websocket-interface.md).\nWeb host chapter: [Web host](chapter:host-web).\n\n## TCP / AutoInterface / Bonjour\n\nDesktop and mobile worklets enable TCP client mode, LAN multicast (AutoInterface),\nand Bonjour discovery when the platform permits. iOS multicast requires the\nnetworking multicast entitlement; web hosts omit these entirely.\n\n## BLE phone pipe\n\nAndroid and iOS expose a BLE GATT byte stream for peer links. Web Bluetooth is\ncentral-only and not used for the phone-pipe role. Device-gated Handbook probes:\n[Device-gated probes](chapter:device-gated-probes).\n\n## RNode serial\n\nUSB serial on desktop/Android; BLE-only on iOS. WebSerial (Chromium) is optional.\nLoRa bandwidth budgets apply — see [LIMITATIONS.md](../../../LIMITATIONS.md) §6.\n"},{"path":"chapters/ref-packages/source.md","content":"# Package format\n\nMini-apps ship as deterministic **`.tpkg`** archives:\n\n- Signed manifest (name, version, entry, capabilities, publisher key, `minHostApi`)\n- Entry bundle (`bundle.js`) and assets\n- Ed25519 signature over the manifest hash\n\nPackaging flow: [Packaging & preview](chapter:sdk-apps-package).\n256t distribution: [docs/256t-distribution.md](../../../docs/256t-distribution.md).\n"},{"path":"chapters/ref-quotas/source.md","content":"# Quotas & limits\n\nGenerated from `DEFAULT_QUOTAS` (`host-core`) and miniapp-runtime defaults.\n`host.info()` includes a quota snapshot for diagnostics.\n\n## Host node quotas (desktop / `tp node`)\n\n- Seed storage: 2147483648 bytes\n- Propagation store: 268435456 bytes\n- Propagation messages: 10000\n- Bandwidth cap: 524288 bytes/s\n\nOverride in `<data-dir>/config.json` — see [Host configuration](chapter:ref-host-config).\n\n## Mini-app workspace (`workspace` capability)\n\n- 262144 bytes per file\n- 4194304 bytes total per app\n- 512 files per app\n\n## Widget & AI limits\n\n- Widget tree JSON: 256 KiB (default validator)\n- AI chat: 64 messages, 8192 max tokens cap\n\n## Transport budgets\n\nBLE install budgets (~180 KiB at measured rates) and Resource fetch caps are\nenforced per link type. See [Resource fetch](chapter:sdk-resource-fetch) and\n`conformance/budgets/measured.json`.\n"},{"path":"chapters/ref-widgets/source.md","content":"# Widget protocol\n\nGenerated from `WIDGET_TYPES` / `WIDGET_PROP_KEYS` in `packages/miniapp-runtime`.\n\nHosts render a declarative tree (`ui.render`). Unknown types, props, styles,\nduplicate ids, or oversized trees are rejected.\n\n## Components\n\n- **`button`** — props: `event`, `label`\n- **`code-editor`** — props: `documentId`, `event`, `language`, `readOnly`\n- **`divider`** — props: none\n- **`image`** — props: `alt`, `asset`\n- **`list`** — props: `event`, `items`\n- **`progress`** — props: `max`, `value`\n- **`qr-code`** — props: `caption`, `size`, `value`\n- **`scroll`** — props: `event`\n- **`spacer`** — props: `size`\n- **`switch`** — props: `event`, `value`\n- **`text`** — props: `value`\n- **`text-input`** — props: `event`, `placeholder`, `value`\n- **`view`** — props: `accessibilityLabel`\n\n## Styles\n\n- `alignItems`\n- `backgroundColor`\n- `color`\n- `display`\n- `flexDirection`\n- `fontSize`\n- `fontWeight`\n- `gap`\n- `height`\n- `justifyContent`\n- `margin`\n- `padding`\n- `width`\n\n## Limits\n\n- Widget tree JSON budget: 256 KiB (default validator)\n- `code-editor` languages: javascript, json, text\n- `qr-code` value: up to 512 characters (94-char 256t ids fit)\n\nLive gallery: [Widget gallery](chapter:sdk-widget-gallery).\n"},{"path":"chapters/reticulum-fundamentals/source.md","content":"# Reticulum fundamentals\n\nReticulum is a cryptography-based networking stack designed for constrained and\nunreliable links. TwistedPear uses it as the only hard networking constraint.\n\n## Building blocks\n\n- **Identity** — an X25519/Ed25519 keypair. Destinations are derived hashes.\n- **Announce** — a signed public advertisement that a destination is reachable.\n- **Link** — an encrypted channel between two destinations.\n- **Resource** — a bulk transfer over a link (used when Hyperswarm is unavailable).\n- **LXMF** — store-and-forward messaging on top of Reticulum.\n\n## App-scoped destinations\n\nMini-apps never hold private keys. The host derives an **app destination** from\nthe device identity plus the app id. Bulk transfer when IP is available:\n[Pears bulk plane](chapter:pears-bulk-plane). See [Concepts in practice](chapter:concepts-in-practice)\nfor a live identity probe, or [Identity & signing](chapter:sdk-identity).\n"},{"path":"chapters/running-diagnostics/source.md","content":"# Running diagnostics\n\nEach applet reports `{ appletId, status, details, timings }` with first-class\n`unavailable` and `not-granted` outcomes.\n\n## On this screen\n\nFrom the Handbook **Contents**, use:\n\n- **Run all diagnostics** — runs every catalog applet inline on this host, grouped\n  by area (crypto, interfaces, storage, distribution, runtime)\n- **Export report** — packs host info + results into JSON, stores via `share.put`,\n  shows a 256t id / QR\n- **Compare report** — paste another device's report id to render a status matrix\n\nOpen an SDK chapter and tap **Run applet** for a single probe.\n\n## Software-tier probes\n\n- Host info — `host.info` (`presence`)\n- App destination hash — `identity`\n- Presence snapshot — `presence`\n- KV round-trip — `storage:kv`\n- Hyperbee round-trip — `storage:hyperbee`\n- LXMF self-message — `identity`, `lxmf:*`\n- Announce publish/subscribe — `announce:*`\n- Resource fetch — `resource:fetch`\n- Workspace read/write — `workspace`\n- CAS share — `share:cas`\n- Package + preview — `apps:package`, `apps:preview`\n- Publish + install — `apps:publish`, `apps:install`\n- AI chat — `ai:chat`\n- Widget gallery — widget protocol\n\nDevice-gated probes (BLE peer, RNode, multicast, camera QR) live in\n[Device-gated probes](chapter:device-gated-probes) — they report `unavailable` in CI\nand simulators with guided procedures for real hardware.\n"},{"path":"chapters/sdk-ai-chat/sample-0.js","content":"import { ai } from \"@twistedpear/miniapp-sdk\";\n\nconst response = await ai.chat({\n  messages: [{ role: \"user\", content: \"hello\" }]\n});\n"},{"path":"chapters/sdk-ai-chat/source.md","content":"# AI chat\n\n`ai:chat` sends prompts to the host-configured OpenRouter-compatible endpoint.\nThe host clamps budgets, enforces a model allowlist, and allows one in-flight\nrequest per app. The API key never enters the sandbox.\n\n## API\n\n```javascript\nimport { ai } from \"@twistedpear/miniapp-sdk\";\n\nconst response = await ai.chat({\n  messages: [{ role: \"user\", content: \"hello\" }]\n});\n```\n\n## Live probe\n\nHosts without an AI endpoint report `unavailable`. When configured, the applet\nbelow exercises a single round-trip.\n\n{{applet:ai-chat}}\n"},{"path":"chapters/sdk-announce/sample-0.js","content":"import { announce } from \"@twistedpear/miniapp-sdk\";\n\nawait announce.publish(appDataBytes, \"my-namespace\");\nconst events = await announce.subscribe(\"my-namespace\");\n"},{"path":"chapters/sdk-announce/source.md","content":"# Announce & subscribe\n\nAnnounces are how destinations advertise reachability. Mini-apps publish and\nsubscribe in an app namespace through the host broker.\n\n## API\n\n```javascript\nimport { announce } from \"@twistedpear/miniapp-sdk\";\n\nawait announce.publish(appDataBytes, \"my-namespace\");\nconst events = await announce.subscribe(\"my-namespace\");\n```\n\n## Live probe\n\n{{applet:announce-loop}}\n"},{"path":"chapters/sdk-apps-package/sample-0.js","content":"import { apps } from \"@twistedpear/miniapp-sdk\";\n\nconst packed = await apps.packageProject(\"my-app\", manifest);\nconst { launched } = await apps.preview(\"my-app\", manifest, grants);\nawait apps.stopPreview();\n"},{"path":"chapters/sdk-apps-package/source.md","content":"# Packaging & preview\n\n`apps:package` and `apps:preview` are double-gated: the capability grant plus a\nhost-chrome confirmation the mini-app cannot dismiss. Package signs under the\ndevice publisher identity; preview runs the project in the single sandboxed\ndev-preview slot.\n\n## API\n\n```javascript\nimport { apps } from \"@twistedpear/miniapp-sdk\";\n\nconst packed = await apps.packageProject(\"my-app\", manifest);\nconst { launched } = await apps.preview(\"my-app\", manifest, grants);\nawait apps.stopPreview();\n```\n\n## Live probe\n\nUse **Run applet** for the automated inline probe (package → preview → stop, used in CI).\n\nUse **Run as real app** to launch the sample in the host dev-preview slot — the full\nsandbox/grant/launch loop with host confirmation. Stop preview when finished.\n\n{{applet:apps-package-preview}}\n"},{"path":"chapters/sdk-apps-publish/sample-0.js","content":"import { apps } from \"@twistedpear/miniapp-sdk\";\n\nawait apps.publish(t256);\nconst installed = await apps.install(t256);\n"},{"path":"chapters/sdk-apps-publish/source.md","content":"# Publish & install\n\n`apps:publish` announces a packaged 256t id under the publisher identity.\n`apps:install` asks the host to fetch, verify, and review capabilities before\nanything runs. Both raise a confirmation dialog on every call.\n\n## API\n\n```javascript\nimport { apps } from \"@twistedpear/miniapp-sdk\";\n\nawait apps.publish(t256);\nconst installed = await apps.install(t256);\n```\n\n## Live probe\n\n{{applet:apps-publish-install}}\n"},{"path":"chapters/sdk-budgets/sample-0.js","content":"import { resource } from \"@twistedpear/miniapp-sdk\";\n\nconst bytes = await resource.fetch({\n  resourceId: \"offer:demo\",\n  budgetBytes: 4096\n});\n"},{"path":"chapters/sdk-budgets/source.md","content":"# Budgets & quotas\n\nHosts enforce limits at several layers so constrained links (BLE, LoRa) and\nshared devices stay predictable. Budgets are not optional hints — exceeding them\nreturns typed errors or truncated transfers.\n\n## Resource fetch (per call)\n\n`resource:fetch` takes an explicit `budgetBytes` cap. The host pulls through\nits link strategy without exposing sockets to the sandbox.\n\n```javascript\nimport { resource } from \"@twistedpear/miniapp-sdk\";\n\nconst bytes = await resource.fetch({\n  resourceId: \"offer:demo\",\n  budgetBytes: 4096\n});\n```\n\n{{applet:resource-fetch}}\n\n## Package install (per transport)\n\n`conformance/budgets/measured.json` records install time at measured bitrates.\nThe BLE guidance target is ~180 KiB for under-one-minute installs; this full\nHandbook is ~165 KiB (~55 s at measured BLE rates) — intentionally above the\ntiny-app example budget.\n\n| Package | Size | LAN | BLE | RNode |\n|---|---|---|---|---|\n| tiny hello | < 1 KiB | ~1 s | ~1 s | ~6 s |\n| handbook (full) | ~165 KiB | ~1 s | ~55 s | ~19 min |\n\nSplit per-part Handbook packages if BLE install of the full catalog matters.\n\n## Host & workspace quotas\n\nNode seeding, propagation store, bandwidth caps, workspace file limits, widget\ntree size, and AI message caps are listed in [Quotas & limits](chapter:ref-quotas).\nOverride desktop/node defaults in `<data-dir>/config.json` — see\n[Host configuration](chapter:ref-host-config).\n"},{"path":"chapters/sdk-capabilities/sample-0.json","content":"{\n  \"capabilities\": [\n    \"identity\",\n    \"storage:kv\",\n    \"workspace\"\n  ]\n}\n"},{"path":"chapters/sdk-capabilities/sample-1.js","content":"import { identity } from \"@twistedpear/miniapp-sdk\";\n\ntry {\n  await identity.destinationHash();\n} catch (error) {\n  if (error?.code === \"CAPABILITY_DENIED\") {\n    // Explain what identity would allow; offer to open Settings\n  }\n}\n"},{"path":"chapters/sdk-capabilities/source.md","content":"# Capability model\n\nMini-apps declare every SDK surface they may use in `app.manifest.json`. At\ninstall the host shows the full list; the user may grant a **subset**. The\nbroker enforces grants on every call — withheld capabilities are not errors in\nthe Handbook, they become `not-granted` teaching cards.\n\n## Manifest\n\n```json\n{\n  \"capabilities\": [\n    \"identity\",\n    \"storage:kv\",\n    \"workspace\"\n  ]\n}\n```\n\nOnly ids from `CAPABILITY_DEFINITIONS` are valid. The reference list is\ngenerated at build time: [Capabilities](chapter:ref-capabilities).\n\n## Typed errors\n\nThe runtime throws `CapabilityError` with a stable `code`:\n\n| Code | Meaning |\n|---|---|\n| `UNKNOWN_CAPABILITY` | Manifest names a capability the host does not recognize |\n| `UNDECLARED_CAPABILITY` | Code calls a capability not listed in the manifest |\n| `CAPABILITY_DENIED` | Manifest lists it but the user withheld the grant |\n\n```javascript\nimport { identity } from \"@twistedpear/miniapp-sdk\";\n\ntry {\n  await identity.destinationHash();\n} catch (error) {\n  if (error?.code === \"CAPABILITY_DENIED\") {\n    // Explain what identity would allow; offer to open Settings\n  }\n}\n```\n\n## Live probe\n\nWithhold `identity` at install (or tap **Revoke** in host settings) and re-run\nthe applet — it reports `not-granted` instead of throwing into your UI.\n\n{{applet:identity-hash}}\n\nDouble-gated capabilities (`apps:package`, `apps:publish`, `apps:install`,\n`apps:preview`) also require a host-chrome confirmation the sandbox cannot\ndismiss. See [Packaging & preview](chapter:sdk-apps-package).\n"},{"path":"chapters/sdk-devstudio/source.md","content":"# DevStudio walkthrough\n\n[DevStudio](../../../docs/devstudio.md) is a mini-app IDE — same sandbox and\ncapability model as any other app. Desktop first-boot seeds it alongside this\nHandbook.\n\n## Development loop\n\n1. **New project** — DevStudio seeds `hello-app/app.json` + `bundle.js` in the\n   app workspace.\n2. **Edit** — the `code-editor` widget is content-by-reference: the tree carries\n   a `documentId`; edits flow back as events and persist with `workspace.write`.\n3. **AI assist** — with `ai:chat` granted, describe a change; the host holds the\n   API key and model (never in the sandbox). Review whole-file proposals before\n   **Apply**.\n4. **Preview** — `apps:preview` runs the project in the single dev-preview slot\n   while DevStudio keeps running.\n5. **Package & sign** — host confirmation; deterministic `.tpkg` under the\n   device publisher identity; 256t id + QR.\n6. **Publish** — host confirmation; seed on Hyperdrive and announce the locator.\n\n## Open in DevStudio from the Handbook\n\nEvery applet card includes **Open in DevStudio**. The Handbook exports the\napplet source plus a `tp.devstudio.workspace.v1` handoff via `share:cas`; paste\nor scan the QR in DevStudio to import the sample as a starting project.\n\nTry it on the identity probe below, then continue in DevStudio with\n[Packaging & preview](chapter:sdk-apps-package).\n\n{{applet:identity-hash}}\n"},{"path":"chapters/sdk-identity/sample-0.js","content":"import { identity } from \"@twistedpear/miniapp-sdk\";\n\nconst hash = await identity.destinationHash();\nconst signature = await identity.sign(payloadBytes);\n"},{"path":"chapters/sdk-identity/source.md","content":"# Identity & signing\n\nThe `identity` capability grants an app-scoped destination and brokered signing.\nPrivate keys never enter the sandbox.\n\n## API\n\n```javascript\nimport { identity } from \"@twistedpear/miniapp-sdk\";\n\nconst hash = await identity.destinationHash();\nconst signature = await identity.sign(payloadBytes);\n```\n\n## Live probe\n\nThe applet below calls `identity.destinationHash()` on this host and reports\npass / fail / not-granted.\n\n{{applet:identity-hash}}\n\nUse **Open in DevStudio** on any applet to copy the sample into a DevStudio\nproject via `share:cas`. Concept overview: [Concepts in practice](chapter:concepts-in-practice).\n"},{"path":"chapters/sdk-lxmf/sample-0.js","content":"import { lxmf } from \"@twistedpear/miniapp-sdk\";\n\nawait lxmf.send({ to: peerAppId, subject: \"hello\", body: \"hi\" });\nconst inbox = await lxmf.receive();\n"},{"path":"chapters/sdk-lxmf/source.md","content":"# LXMF messaging\n\n`lxmf:send` and `lxmf:receive` give a mini-app a namespaced mailbox. Private\nkeys stay in the host; the app only sees deliveries for its destination.\n\n## API\n\n```javascript\nimport { lxmf } from \"@twistedpear/miniapp-sdk\";\n\nawait lxmf.send({ to: peerAppId, subject: \"hello\", body: \"hi\" });\nconst inbox = await lxmf.receive();\n```\n\n## Live probe\n\n{{applet:lxmf-roundtrip}}\n\nSee also [Identity & signing](chapter:sdk-identity).\n"},{"path":"chapters/sdk-presence/sample-0.js","content":"import { presence, host } from \"@twistedpear/miniapp-sdk\";\n\nconst snap = await presence.snapshot();\n// { onlineInterfaces, preferredInterface, peers }\n\nconst info = await host.info();\n// { platform, hostVersion, hostApiVersion, roles, interfaceTypes, quotas }\n"},{"path":"chapters/sdk-presence/source.md","content":"# Presence\n\nThe `presence` capability lets a mini-app read coarse peer and interface state\nand host metadata (`host.info`) without raw sockets or interface handles.\n\n## API\n\n```javascript\nimport { presence, host } from \"@twistedpear/miniapp-sdk\";\n\nconst snap = await presence.snapshot();\n// { onlineInterfaces, preferredInterface, peers }\n\nconst info = await host.info();\n// { platform, hostVersion, hostApiVersion, roles, interfaceTypes, quotas }\n```\n\n## Live probe\n\n{{applet:presence-snapshot}}\n\nSee also the [live difference matrix](chapter:difference-matrix) (`host.info`).\n"},{"path":"chapters/sdk-resource-fetch/sample-0.js","content":"import { resource } from \"@twistedpear/miniapp-sdk\";\n\nconst bytes = await resource.fetch({\n  resourceId: \"offer:demo\",\n  budgetBytes: 4096\n});\n"},{"path":"chapters/sdk-resource-fetch/source.md","content":"# Resource fetch\n\n`resource:fetch` asks the host to pull a Resource through its budget rules.\nThe mini-app never sees sockets or peer handles — only bytes (or a typed error).\n\n## API\n\n```javascript\nimport { resource } from \"@twistedpear/miniapp-sdk\";\n\nconst bytes = await resource.fetch({\n  resourceId: \"offer:demo\",\n  budgetBytes: 4096\n});\n```\n\n## Live probe\n\n{{applet:resource-fetch}}\n"},{"path":"chapters/sdk-share-cas/sample-0.js","content":"import { share } from \"@twistedpear/miniapp-sdk\";\n\nconst { t256, size } = await share.put(\"hello\");\nconst again = await share.get(t256);\n"},{"path":"chapters/sdk-share-cas/source.md","content":"# Content-addressed share\n\n`share:cas` stores a bounded string and returns a 94-character 256t id.\nPaste or scan that id on another device to `share.get` the same bytes —\ndiagnostics reports and DevStudio hand-offs use this path.\n\n## API\n\n```javascript\nimport { share } from \"@twistedpear/miniapp-sdk\";\n\nconst { t256, size } = await share.put(\"hello\");\nconst again = await share.get(t256);\n```\n\n## Live probe\n\n{{applet:share-cas}}\n"},{"path":"chapters/sdk-storage-hyperbee/sample-0.js","content":"import { storage } from \"@twistedpear/miniapp-sdk\";\n\nawait storage.bee.open();\nawait storage.bee.put(\"post:1\", bytes);\nconst value = await storage.bee.get(\"post:1\");\nconst entries = await storage.bee.list({ limit: 10 });\nawait storage.bee.del(\"post:1\");\n"},{"path":"chapters/sdk-storage-hyperbee/source.md","content":"# Hyperbee storage\n\n`storage:hyperbee` opens a local-only ordered key/value store (Hyperbee)\nnamespaced to the app. Keys stay sorted so list ranges are useful for feeds\nand indexes.\n\n## API\n\n```javascript\nimport { storage } from \"@twistedpear/miniapp-sdk\";\n\nawait storage.bee.open();\nawait storage.bee.put(\"post:1\", bytes);\nconst value = await storage.bee.get(\"post:1\");\nconst entries = await storage.bee.list({ limit: 10 });\nawait storage.bee.del(\"post:1\");\n```\n\n## Live probe\n\n{{applet:storage-hyperbee}}\n"},{"path":"chapters/sdk-storage-kv/sample-0.js","content":"import { storage } from \"@twistedpear/miniapp-sdk\";\n\nawait storage.kv.set(\"key\", bytes);\nconst value = await storage.kv.get(\"key\");\nawait storage.kv.delete(\"key\");\n"},{"path":"chapters/sdk-storage-kv/source.md","content":"# Key/value storage\n\n`storage:kv` is a per-app local store with a byte quota enforced by the host.\n\n## API\n\n```javascript\nimport { storage } from \"@twistedpear/miniapp-sdk\";\n\nawait storage.kv.set(\"key\", bytes);\nconst value = await storage.kv.get(\"key\");\nawait storage.kv.delete(\"key\");\n```\n\n## Live probe\n\n{{applet:storage-kv}}\n"},{"path":"chapters/sdk-widget-gallery/source.md","content":"# Widget gallery\n\nThe widget protocol is the cross-platform UI seam. Allowed components:\n`view`, `text`, `image`, `button`, `text-input`, `switch`, `scroll`, `list`,\n`progress`, `divider`, `spacer`, `code-editor`, `qr-code`.\n\n`code-editor` is content-by-reference (workspace `documentId`); `qr-code` is\nsized for 94-character 256t ids. The host rejects unknown props, styles,\nduplicate ids, and oversized trees.\n\n## Live probe\n\nThe applet submits a tree that includes every component type. After it reports,\nthe Handbook re-renders this chapter with the result card.\n\n{{applet:widget-gallery}}\n"},{"path":"chapters/sdk-workspace/sample-0.js","content":"import { workspace } from \"@twistedpear/miniapp-sdk\";\n\nawait workspace.write(\"src/main.js\", source);\nconst text = await workspace.read(\"src/main.js\");\nconst files = await workspace.list(\"src/\");\nawait workspace.remove(\"src/main.js\");\n"},{"path":"chapters/sdk-workspace/source.md","content":"# Workspace\n\n`workspace` is a private per-app project filesystem of relative paths\n(strings; 256 KiB/file, 4 MiB and 512 files per app). DevStudio and this\nHandbook use it for sources and applet seeds.\n\n## API\n\n```javascript\nimport { workspace } from \"@twistedpear/miniapp-sdk\";\n\nawait workspace.write(\"src/main.js\", source);\nconst text = await workspace.read(\"src/main.js\");\nconst files = await workspace.list(\"src/\");\nawait workspace.remove(\"src/main.js\");\n```\n\n## Live probe\n\n{{applet:workspace-rw}}\n"},{"path":"chapters/what-is-twistedpear/source.md","content":"# What TwistedPear is\n\nTwistedPear is a peer-to-peer app platform. A **host** on each device is a full\nReticulum peer; **mini-apps** are sandboxed JavaScript bundles that talk to the\nhost only through the SDK.\n\n## Two planes\n\n- **Control plane** — Reticulum handles identity, announces, links, LXMF, and\n  off-grid Resource transfer.\n- **Bulk plane** — Hypercore / Hyperdrive / Hyperswarm carry large package\n  syncs when IP connectivity exists. [Pears bulk plane](chapter:pears-bulk-plane).\n\n## Trust model\n\nPublisher identity **is** network identity. Packages are Ed25519-signed with the\ndeveloper's Reticulum key, so discovering an app and trusting its author use the\nsame root.\n\n## This Handbook\n\nThis document is itself a mini-app. If it installed and rendered on *this* host,\nyou have already exercised packaging, install, sandbox, broker, and the widget\nrenderer. Chapters later add interactive applets that probe live capabilities.\n\nOpen **Diagnostics** from the table of contents to run every probe, export a\nreport, or compare against another device. Reference pages in Part V are\ngenerated from the same runtime sources the host uses. Host-specific behavior:\n[Part II — The hosts](chapter:host-desktop).\n"}]};
import {
  ai,
  apps,
  announce,
  host,
  identity,
  lxmf,
  presence,
  resource,
  share,
  storage,
  ui,
  workspace
} from "@twistedpear/miniapp-sdk";

// Handbook runtime — TOC, chapter renderer, inline applet runner, diagnostics.
// CATALOG is injected by build.mjs immediately above this file in bundle.js.

const POSITION_KEY = "handbook:position";
const SEEDED_KEY = "handbook:seeded";
const SEED_VERSION_KEY = "handbook:seed-version";
const GRANT_INTRO_KEY = "handbook:grant-intro-seen";
const LAST_REPORT_KEY = "handbook:last-report";
const REPORT_SCHEMA_VERSION = 1;
const DEVSTUDIO_HANDOFF_KIND = "tp.devstudio.workspace.v1";

const DIAGNOSTIC_GROUP_ORDER = ["crypto", "interfaces", "storage", "distribution", "runtime"];
const DIAGNOSTIC_GROUP_LABELS = {
  crypto: "Crypto & messaging",
  interfaces: "Interfaces & presence",
  storage: "Storage & workspace",
  distribution: "Distribution & fetch",
  runtime: "Runtime & UI"
};

/** @type {"toc" | "chapter" | "diagnostics" | "grant-intro"} */
let view = "toc";
/** @type {string | null} */
let chapterId = null;
/** @type {Record<string, { status: string, details: string, timings?: { ms: number } }>} */
let appletResults = {};
/** @type {string | null} */
let statusLine = null;
/** @type {boolean} */
let seeding = false;
/** @type {boolean} */
let runningAll = false;
/** @type {{ reportId: string | null, generatedAt: string | null, json: string | null }} */
let exportState = { reportId: null, generatedAt: null, json: null };
/** @type {string} */
let compareInput = "";
/** @type {{ local: object | null, remote: object | null, rows: Array<object>, error: string | null }} */
let compareState = { local: null, remote: null, rows: [], error: null };
/** @type {Record<string, { t256: string, project: string }>} */
let devstudioHandoffs = {};
/** @type {boolean} */
let previewRunning = false;
/** @type {string | null} */
let previewAppletId = null;

function appletSupportsMode(applet, mode) {
  const modes = applet.executionModes ?? ["inline"];
  return modes.includes(mode);
}

function makeSdk() {
  return {
    identity,
    presence,
    host,
    announce,
    lxmf,
    storage,
    resource,
    workspace,
    ui,
    share,
    apps,
    ai
  };
}

function findChapter(id) {
  return CATALOG.chapters.find((chapter) => chapter.id === id) ?? null;
}

function findApplet(id) {
  return CATALOG.applets.find((applet) => applet.id === id) ?? null;
}

async function kvGetText(key) {
  const bytes = await storage.kv.get(key);
  if (bytes === null) {
    return null;
  }
  return new TextDecoder().decode(bytes);
}

async function kvSetText(key, value) {
  await storage.kv.set(key, new TextEncoder().encode(value));
}

async function ensureSeeds() {
  const version = await kvGetText(SEED_VERSION_KEY);
  const seeded = await kvGetText(SEEDED_KEY);
  if (seeded === "1" && version === CATALOG.version) {
    return;
  }

  seeding = true;
  try {
    for (const seed of CATALOG.seeds) {
      await workspace.write(seed.path, seed.content);
    }
    await kvSetText(SEEDED_KEY, "1");
    await kvSetText(SEED_VERSION_KEY, CATALOG.version);
  } finally {
    seeding = false;
  }
}

function widgetButton(id, label, event) {
  return { id, type: "button", props: { label, event } };
}

function textNode(id, value, style) {
  const node = { id, type: "text", props: { value } };
  if (style !== undefined) {
    node.style = style;
  }
  return node;
}

function headingStyle(level) {
  if (level === 1) {
    return { fontSize: 24, fontWeight: "bold" };
  }
  if (level === 2) {
    return { fontSize: 20, fontWeight: "bold" };
  }
  return { fontSize: 16, fontWeight: "bold" };
}

function resultCard(appletId, result) {
  if (result === undefined) {
    return textNode(`result-${appletId}-empty`, "Not run yet.");
  }

  const label = result.status.toUpperCase();
  const timing =
    result.timings && typeof result.timings.ms === "number" ? ` (${result.timings.ms} ms)` : "";
  return textNode(
    `result-${appletId}`,
    `${label}${timing}\n${result.details}`
  );
}

function explainStatus(status) {
  if (status === "not-granted") {
    return "This capability was withheld for this app. Grant it at install to run the probe.";
  }
  if (status === "unavailable") {
    return "This host does not implement the feature; that is an expected platform difference.";
  }
  if (status === "skipped") {
    return "Skipped.";
  }
  return null;
}

function renderTableBlock(bid, block, children) {
  children.push(
    textNode(`${bid}-header`, block.headers.join(" · "), { fontWeight: "bold" })
  );
  const items = block.rows.map((row) => row.join(" — "));
  children.push({
    id: `${bid}-rows`,
    type: "list",
    props: { items }
  });
}

async function renderGrantIntro(children) {
  children.push(
    textNode("grant-intro-title", "Capabilities at install", { fontSize: 20, fontWeight: "bold" })
  );
  children.push(
    textNode(
      "grant-intro-blurb",
      "The Handbook requested the capabilities below. You may grant a subset at install — withheld capabilities turn matching applets into not-granted teaching cards instead of errors."
    )
  );

  /** @type {Set<string>} */
  let granted = new Set();
  try {
    const info = await host.info();
    if (Array.isArray(info.grantedCapabilities)) {
      granted = new Set(info.grantedCapabilities);
    }
  } catch {
    // presence withheld — list manifest capabilities without live grant status
  }

  const caps = CATALOG.manifestCapabilities ?? [];
  for (let i = 0; i < caps.length; i += 1) {
    const cap = caps[i];
    const status =
      granted.size === 0
        ? ""
        : granted.has(cap.id)
          ? " ✓ granted"
          : " ✗ withheld";
    children.push(textNode(`grant-cap-${i}`, `• ${cap.id} — ${cap.description}${status}`));
  }

  children.push(
    textNode(
      "grant-intro-note",
      "Revoke or add grants later in host Settings. Double-gated apps:* capabilities also require a host confirmation on each call."
    )
  );
  children.push(
    widgetButton("grant-intro-continue", "Continue to Handbook", "hb.grantintro.dismiss")
  );
}

function appletsByDiagnosticGroup() {
  /** @type {Record<string, typeof CATALOG.applets>} */
  const grouped = {};
  for (const group of DIAGNOSTIC_GROUP_ORDER) {
    grouped[group] = [];
  }
  for (const applet of CATALOG.applets) {
    const group = applet.group ?? "runtime";
    if (grouped[group] === undefined) {
      grouped[group] = [];
    }
    grouped[group].push(applet);
  }
  return grouped;
}

function renderAppletBlock(appletId, children) {
  const applet = findApplet(appletId);
  if (applet === null) {
    children.push(textNode(`missing-${appletId}`, `Missing applet: ${appletId}`));
    return;
  }

  children.push({ id: `applet-sep-${appletId}`, type: "divider" });
  children.push(
    textNode(`applet-title-${appletId}`, `Applet: ${applet.title}`, {
      fontSize: 16,
      fontWeight: "bold"
    })
  );
  children.push(
    textNode(
      `applet-caps-${appletId}`,
      `Requires: ${applet.capabilities.join(", ")}`
    )
  );
  children.push({
    id: `applet-src-${appletId}`,
    type: "code-editor",
    props: {
      documentId: `applets/${appletId}/main.js`,
      language: "javascript",
      readOnly: true
    }
  });
  children.push(
    widgetButton(`applet-run-${appletId}`, "Run applet", "hb.runapplet")
  );
  if (appletSupportsMode(applet, "preview") && applet.preview !== null) {
    children.push(
      widgetButton(`applet-preview-${appletId}`, "Run as real app", "hb.runpreview")
    );
    if (previewRunning && previewAppletId === appletId) {
      children.push(
        widgetButton(`applet-stoppreview-${appletId}`, "Stop preview", "hb.stoppreview")
      );
      children.push(
        textNode(
          `applet-preview-active-${appletId}`,
          "Preview is running in the host dev-preview slot. Stop preview to return here."
        )
      );
    }
  }
  children.push(
    widgetButton(`applet-devstudio-${appletId}`, "Open in DevStudio", "hb.devstudio")
  );

  const handoff = devstudioHandoffs[appletId];
  if (handoff !== undefined) {
    children.push(
      textNode(
        `applet-devstudio-meta-${appletId}`,
        `DevStudio handoff: ${handoff.project}\nPaste in DevStudio → Import from 256t`
      )
    );
    children.push({
      id: `applet-devstudio-qr-${appletId}`,
      type: "qr-code",
      props: {
        value: handoff.t256,
        caption: handoff.project,
        size: 96
      }
    });
  }

  const result = appletResults[appletId];
  children.push(resultCard(appletId, result));
  if (result !== undefined) {
    const explanation = explainStatus(result.status);
    if (explanation !== null) {
      children.push(textNode(`applet-explain-${appletId}`, explanation));
    }
  }
}

function renderChapterBlocks(chapter, children) {
  let blockIndex = 0;
  for (const block of chapter.blocks) {
    const bid = `${chapter.id}-b${blockIndex++}`;
    if (block.type === "heading") {
      children.push(textNode(bid, block.text, headingStyle(block.level)));
      continue;
    }
    if (block.type === "paragraph") {
      children.push(textNode(bid, block.text));
      continue;
    }
    if (block.type === "list") {
      for (let i = 0; i < block.items.length; i += 1) {
        children.push(textNode(`${bid}-i${i}`, `• ${block.items[i]}`));
      }
      continue;
    }
    if (block.type === "table") {
      renderTableBlock(bid, block, children);
      continue;
    }
    if (block.type === "code") {
      children.push({
        id: bid,
        type: "code-editor",
        props: {
          documentId: block.documentId,
          language: block.language,
          readOnly: true
        }
      });
      continue;
    }
    if (block.type === "chapter-link") {
      children.push(
        widgetButton(`link-${block.chapterId}-${bid}`, `→ ${block.label}`, "hb.openchapter")
      );
      continue;
    }
    if (block.type === "applet") {
      renderAppletBlock(block.appletId, children);
    }
  }
}

async function fetchHostInfoSafe() {
  try {
    return await host.info();
  } catch (error) {
    return {
      platform: "unknown",
      hostVersion: "unknown",
      hostApiVersion: "unknown",
      roles: { transport: false, seeder: false, propagation: false },
      interfaceTypes: [],
      quotas: {
        kvQuotaBytes: null,
        seedStorageUsedBytes: null,
        seedStorageQuotaBytes: null,
        memoryBytes: null
      },
      error: error instanceof Error ? error.message : String(error)
    };
  }
}

function buildReportDocument(hostInfo) {
  const results = CATALOG.applets.map((applet) => {
    const result = appletResults[applet.id];
    if (result === undefined) {
      return {
        appletId: applet.id,
        status: "skipped",
        details: "Not run",
        timings: { ms: 0 }
      };
    }
    return {
      appletId: applet.id,
      status: result.status,
      details: result.details,
      timings: result.timings ?? { ms: 0 }
    };
  });

  return {
    schemaVersion: REPORT_SCHEMA_VERSION,
    handbookVersion: CATALOG.version,
    generatedAt: new Date().toISOString(),
    host: hostInfo,
    results
  };
}

function diffReports(localReport, remoteReport) {
  const remoteById = new Map(
    (remoteReport.results ?? []).map((row) => [row.appletId, row])
  );
  const rows = [];
  for (const local of localReport.results ?? []) {
    const remote = remoteById.get(local.appletId);
    rows.push({
      appletId: local.appletId,
      local: local.status,
      remote: remote?.status ?? "missing",
      same: remote !== undefined && remote.status === local.status
    });
  }
  return rows;
}

function renderDiagnostics(children) {
  children.push(widgetButton("back-toc-diag", "← Contents", "hb.toc"));
  children.push({ id: "diag-sep", type: "divider" });
  children.push(textNode("diag-title", "Diagnostics", { fontSize: 20, fontWeight: "bold" }));
  children.push(
    textNode(
      "diag-blurb",
      "Run every applet on this host, export a shareable report, or paste another report’s 256t id to compare."
    )
  );

  children.push(
    widgetButton(
      "diag-run-all",
      runningAll ? "Running all…" : "Run all diagnostics",
      "hb.runall"
    )
  );

  const counts = { pass: 0, fail: 0, unavailable: 0, "not-granted": 0, skipped: 0 };
  const grouped = appletsByDiagnosticGroup();
  for (const group of DIAGNOSTIC_GROUP_ORDER) {
    const applets = grouped[group];
    if (applets === undefined || applets.length === 0) {
      continue;
    }
    children.push(
      textNode(
        `diag-group-${group}`,
        DIAGNOSTIC_GROUP_LABELS[group] ?? group,
        { fontSize: 14, fontWeight: "bold" }
      )
    );
    for (const applet of applets) {
      const result = appletResults[applet.id];
      const status = result?.status ?? "skipped";
      if (counts[status] !== undefined) {
        counts[status] += 1;
      }
      children.push(
        textNode(
          `diag-row-${applet.id}`,
          `  ${applet.id}: ${status.toUpperCase()}`
        )
      );
    }
  }
  children.push(
    textNode(
      "diag-summary",
      `Summary — pass ${counts.pass}, fail ${counts.fail}, unavailable ${counts.unavailable}, not-granted ${counts["not-granted"]}, skipped ${counts.skipped}`
    )
  );

  children.push({ id: "diag-export-sep", type: "divider" });
  children.push(widgetButton("diag-export", "Export report (share.put)", "hb.export"));
  if (exportState.reportId !== null) {
    children.push(
      textNode(
        "diag-export-meta",
        `Exported ${exportState.generatedAt ?? ""}\n${exportState.reportId}`
      )
    );
    children.push({
      id: "diag-export-qr",
      type: "qr-code",
      props: {
        value: exportState.reportId,
        caption: "Scan or copy report 256t id"
      }
    });
  }

  children.push({ id: "diag-compare-sep", type: "divider" });
  children.push(textNode("diag-compare-label", "Compare with remote report id:"));
  children.push({
    id: "diag-compare-input",
    type: "text-input",
    props: {
      value: compareInput,
      placeholder: "Paste 256t id",
      event: "hb.compare.input"
    }
  });
  children.push(widgetButton("diag-compare", "Compare report", "hb.compare"));

  if (compareState.error !== null) {
    children.push(textNode("diag-compare-error", compareState.error));
  }
  if (compareState.rows.length > 0) {
    const localPlat = compareState.local?.host?.platform ?? "?";
    const remotePlat = compareState.remote?.host?.platform ?? "?";
    children.push(
      textNode(
        "diag-compare-hosts",
        `Local host: ${localPlat}  ·  Remote host: ${remotePlat}`
      )
    );
    const grouped = appletsByDiagnosticGroup();
    for (const group of DIAGNOSTIC_GROUP_ORDER) {
      const applets = grouped[group];
      if (applets === undefined || applets.length === 0) {
        continue;
      }
      const groupRows = compareState.rows.filter((row) =>
        applets.some((applet) => applet.id === row.appletId)
      );
      if (groupRows.length === 0) {
        continue;
      }
      children.push(
        textNode(
          `diag-compare-group-${group}`,
          DIAGNOSTIC_GROUP_LABELS[group] ?? group,
          { fontSize: 14, fontWeight: "bold" }
        )
      );
      for (const row of groupRows) {
        const mark = row.same ? "=" : "≠";
        children.push(
          textNode(
            `diag-diff-${row.appletId}`,
            `  ${mark} ${row.appletId}: ${row.local} / ${row.remote}`
          )
        );
      }
    }
  }
}

async function render() {
  const children = [
    textNode("brand", CATALOG.title, { fontSize: 24, fontWeight: "bold" })
  ];

  if (statusLine !== null) {
    children.push(textNode("status", statusLine));
  }

  if (seeding) {
    children.push(textNode("seeding", "Seeding documentation workspace…"));
  }

  if (view === "grant-intro") {
    await renderGrantIntro(children);
  } else if (view === "toc") {
    children.push(textNode("toc-heading", "Contents", { fontSize: 20, fontWeight: "bold" }));
    children.push(
      textNode(
        "toc-blurb",
        "Interactive diagnostic documentation. Open a chapter, then run embedded applets on this host."
      )
    );
    children.push(widgetButton("open-diag", "Diagnostics · run all / export / compare", "hb.diagnostics"));

    for (const part of CATALOG.parts) {
      children.push({ id: `part-sep-${part.id}`, type: "divider" });
      children.push(textNode(`part-${part.id}`, part.title, { fontSize: 16, fontWeight: "bold" }));
      for (const chapter of part.chapters) {
        const marker = chapterId === chapter.id ? "▶ " : "";
        children.push(
          widgetButton(`ch-${chapter.id}`, `${marker}${chapter.title}`, "hb.openchapter")
        );
      }
    }
  } else if (view === "diagnostics") {
    renderDiagnostics(children);
  } else if (view === "chapter") {
    const chapter = findChapter(chapterId);
    children.push(widgetButton("back-toc", "← Contents", "hb.toc"));
    children.push({ id: "chapter-sep", type: "divider" });

    if (chapter === null) {
      children.push(textNode("missing-chapter", `Chapter not found: ${chapterId}`));
    } else {
      children.push(
        textNode("chapter-part", chapter.partTitle, { fontSize: 12, fontWeight: "medium" })
      );
      children.push(
        textNode("chapter-title", chapter.title, { fontSize: 20, fontWeight: "bold" })
      );
      renderChapterBlocks(chapter, children);
    }
  }

  await ui.render({
    root: {
      id: "root",
      type: "scroll",
      style: { padding: 16, gap: 8 },
      children: [
        {
          id: "inner",
          type: "view",
          style: { gap: 8 },
          children
        }
      ]
    }
  });
}

async function openChapter(id) {
  if (findChapter(id) === null) {
    statusLine = `Unknown chapter: ${id}`;
    await render();
    return;
  }

  chapterId = id;
  view = "chapter";
  statusLine = null;
  await kvSetText(POSITION_KEY, id);
  await render();
}

async function dismissGrantIntro() {
  await kvSetText(GRANT_INTRO_KEY, "1");
  view = "toc";
  statusLine = null;
  await render();
}

async function openToc() {
  view = "toc";
  statusLine = null;
  await render();
}

async function openDiagnostics() {
  view = "diagnostics";
  statusLine = null;
  await render();
}

function stripAppletExports(source) {
  return source
    .replace(/export\s+async\s+function\s+run\s*/, "async function run ")
    .replace(/export\s+\{[^}]+\}\s*;?/g, "");
}

/**
 * Load applet `run(sdk, report)`. Prefer AsyncFunction (Node sandbox). Fall back
 * to blob-URL import when CSP blocks eval (browser iframe worker has no
 * unsafe-eval).
 */
async function loadAppletRunner(source) {
  const body = stripAppletExports(source);
  try {
    const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor;
    // Probe — some CSPs allow constructing Function but reject calling it.
    const probe = new AsyncFunction("return 1");
    await probe();
    return new AsyncFunction("sdk", "report", `${body}\nawait run(sdk, report);`);
  } catch {
    const moduleSource = `${body}\nexport async function __handbookRun(sdk, report) {\n  await run(sdk, report);\n}\n`;
    const moduleUrl = URL.createObjectURL(new Blob([moduleSource], { type: "text/javascript" }));
    try {
      const mod = await import(moduleUrl);
      if (typeof mod.__handbookRun !== "function") {
        throw new Error("Applet module did not export __handbookRun");
      }
      return (sdk, report) => mod.__handbookRun(sdk, report);
    } finally {
      URL.revokeObjectURL(moduleUrl);
    }
  }
}

async function runAppletInline(appletId, options = {}) {
  const { quiet = false } = options;
  const applet = findApplet(appletId);
  if (applet === null) {
    if (!quiet) {
      statusLine = `Unknown applet: ${appletId}`;
      await render();
    }
    return null;
  }

  if (!quiet) {
    statusLine = `Running ${applet.title}…`;
    await render();
  }

  let source;
  try {
    source = await workspace.read(`applets/${appletId}/main.js`);
  } catch {
    source = CATALOG.seeds.find((seed) => seed.path === `applets/${appletId}/main.js`)?.content;
  }

  if (typeof source !== "string" || source.length === 0) {
    const failed = {
      status: "fail",
      details: "Applet source not found in workspace seeds."
    };
    appletResults[appletId] = failed;
    if (!quiet) {
      statusLine = null;
      await render();
    }
    return { appletId, ...failed };
  }

  const started = Date.now();
  /** @type {{ status: string, details: string, timings?: { ms: number } } | null} */
  let reported = null;
  const report = (result) => {
    reported = {
      status: result.status,
      details: result.details,
      timings: result.timings ?? { ms: Date.now() - started }
    };
  };

  try {
    const runner = await loadAppletRunner(source);
    await runner(makeSdk(), report);
    if (reported === null) {
      reported = {
        status: "fail",
        details: "Applet finished without calling report().",
        timings: { ms: Date.now() - started }
      };
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    const notGranted =
      /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);
    reported = {
      status: notGranted ? "not-granted" : "fail",
      details: message,
      timings: { ms: Date.now() - started }
    };
  }

  appletResults[appletId] = reported;
  if (!quiet) {
    statusLine = `${applet.title}: ${reported.status}`;
    await render();
  }
  return { appletId, ...reported };
}

async function seedPreviewProject(preview) {
  const project = preview.project;
  for (const [name, content] of Object.entries(preview.files)) {
    await workspace.write(`${project}/${name}`, content);
  }
}

async function runAppletPreviewSlot(appletId) {
  const applet = findApplet(appletId);
  if (applet === null || applet.preview === null || !appletSupportsMode(applet, "preview")) {
    statusLine = `Preview not available for: ${appletId}`;
    await render();
    return;
  }

  if (previewRunning) {
    statusLine = "Stop the current preview before starting another.";
    await render();
    return;
  }

  const preview = applet.preview;
  statusLine = `Launching preview for ${applet.title}…`;
  await render();

  const started = Date.now();
  try {
    await seedPreviewProject(preview);
    const packed = await apps.packageProject(preview.project, preview.manifest);
    if (packed === null || typeof packed.t256 !== "string") {
      throw new Error(`Package failed: ${JSON.stringify(packed)}`);
    }

    const launched = await apps.preview(preview.project, preview.manifest, preview.grants);
    if (launched === null || launched.launched !== true) {
      throw new Error(`Preview did not launch: ${JSON.stringify(launched)}`);
    }

    previewRunning = true;
    previewAppletId = appletId;
    appletResults[appletId] = {
      status: "pass",
      details: `Preview running (${packed.t256.slice(0, 12)}…). Use Stop preview when finished.`,
      timings: { ms: Date.now() - started }
    };
    statusLine = `${applet.title}: preview slot active`;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);
    const unavailable = /not configured|UNCONFIGURED|CONFIRMATION_UNAVAILABLE|unavailable/i.test(
      message
    );
    appletResults[appletId] = {
      status: notGranted ? "not-granted" : unavailable ? "unavailable" : "fail",
      details: message,
      timings: { ms: Date.now() - started }
    };
    statusLine = `${applet.title}: preview failed`;
  }

  await render();
}

async function stopAppletPreview() {
  if (!previewRunning) {
    return;
  }

  try {
    await apps.stopPreview();
  } catch (error) {
    statusLine = `Stop preview failed: ${error instanceof Error ? error.message : String(error)}`;
    await render();
    return;
  }

  previewRunning = false;
  previewAppletId = null;
  statusLine = "Preview stopped";
  await render();
}

async function runAllDiagnostics() {
  if (runningAll) {
    return;
  }
  runningAll = true;
  statusLine = "Running all diagnostics…";
  view = "diagnostics";
  await render();

  try {
    for (const applet of CATALOG.applets) {
      statusLine = `Running ${applet.title}…`;
      await render();
      await runAppletInline(applet.id, { quiet: true });
      // Restore Handbook chrome after applets that call ui.render (e.g. widget gallery).
      statusLine = `Finished ${applet.title}: ${appletResults[applet.id]?.status ?? "?"}`;
      await render();
    }
    statusLine = `All diagnostics finished (${CATALOG.applets.length} applets)`;
  } finally {
    runningAll = false;
    await render();
  }
}

async function exportReport() {
  statusLine = "Building diagnostic report…";
  await render();

  const hostInfo = await fetchHostInfoSafe();
  const document = buildReportDocument(hostInfo);
  const json = JSON.stringify(document);

  try {
    const put = await share.put(json);
    exportState = {
      reportId: put.t256,
      generatedAt: document.generatedAt,
      json
    };
    await kvSetText(LAST_REPORT_KEY, json);
    compareState = { ...compareState, local: document };
    statusLine = `Report exported (${put.t256.slice(0, 12)}…)`;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    exportState = { reportId: null, generatedAt: document.generatedAt, json };
    await kvSetText(LAST_REPORT_KEY, json);
    compareState = { ...compareState, local: document };
    statusLine = `Report built locally but share.put failed: ${message}`;
  }

  view = "diagnostics";
  await render();
}

function buildDevstudioBundle(appletSource) {
  const body = appletSource.replace(/^export\s+async\s+function\s+run\s*\(/m, "async function appletRun(");
  return `import {
  ai,
  apps,
  announce,
  host,
  identity,
  lxmf,
  presence,
  resource,
  share,
  storage,
  ui,
  workspace
} from "@twistedpear/miniapp-sdk";

${body}

function makeSdk() {
  return {
    identity,
    presence,
    host,
    announce,
    lxmf,
    storage,
    resource,
    workspace,
    ui,
    share,
    apps,
    ai
  };
}

let reported = null;
await appletRun(makeSdk(), (result) => {
  reported = result;
});

await ui.render({
  root: {
    id: "root",
    type: "scroll",
    style: { padding: 12, gap: 8 },
    children: [
      {
        id: "result",
        type: "text",
        props: {
          value: reported
            ? \`\${reported.status.toUpperCase()}\\n\${reported.details}\`
            : "Applet finished without calling report()."
        }
      }
    ]
  }
});
`;
}

async function exportAppletToDevStudio(appletId) {
  const applet = findApplet(appletId);
  if (applet === null) {
    statusLine = `Unknown applet: ${appletId}`;
    await render();
    return;
  }

  statusLine = `Preparing DevStudio handoff for ${applet.title}…`;
  await render();

  let source = CATALOG.seeds.find((seed) => seed.path === `applets/${appletId}/main.js`)?.content;
  if (source === undefined) {
    try {
      source = await workspace.read(`applets/${appletId}/main.js`);
    } catch {
      source = undefined;
    }
  }

  if (source === undefined) {
    statusLine = "Applet source not found in workspace seeds.";
    await render();
    return;
  }

  const project = `hb-${appletId}`;
  const manifest = {
    name: project,
    version: "0.1.0",
    entry: "bundle.js",
    capabilities: applet.capabilities
  };
  const payload = {
    kind: DEVSTUDIO_HANDOFF_KIND,
    version: 1,
    project,
    files: [
      { path: `${project}/app.json`, content: JSON.stringify(manifest, null, 2) },
      { path: `${project}/applet.js`, content: source },
      { path: `${project}/bundle.js`, content: buildDevstudioBundle(source) }
    ]
  };

  try {
    const put = await share.put(JSON.stringify(payload));
    devstudioHandoffs[appletId] = { t256: put.t256, project };
    statusLine = `DevStudio handoff ready (${put.t256.slice(0, 12)}…)`;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    const notGranted = /CAPABILITY_DENIED|has not been granted|Capability/i.test(message);
    statusLine = notGranted
      ? "Grant share:cas to export DevStudio handoffs."
      : `DevStudio handoff failed: ${message}`;
  }

  await render();
}

async function compareReport() {
  const t256 = compareInput.trim();
  if (t256.length === 0) {
    compareState = { local: compareState.local, remote: null, rows: [], error: "Paste a report 256t id first." };
    await render();
    return;
  }

  statusLine = "Fetching remote report…";
  await render();

  let local = compareState.local;
  if (local === null) {
    const cached = await kvGetText(LAST_REPORT_KEY);
    if (cached !== null) {
      try {
        local = JSON.parse(cached);
      } catch {
        local = null;
      }
    }
  }
  if (local === null) {
    const hostInfo = await fetchHostInfoSafe();
    local = buildReportDocument(hostInfo);
  }

  try {
    const remoteJson = await share.get(t256);
    if (typeof remoteJson !== "string" || remoteJson.length === 0) {
      compareState = {
        local,
        remote: null,
        rows: [],
        error: "Remote report not found (null content)."
      };
      statusLine = null;
      await render();
      return;
    }
    const remote = JSON.parse(remoteJson);
    const rows = diffReports(local, remote);
    compareState = { local, remote, rows, error: null };
    statusLine = `Compared ${rows.length} applet row(s)`;
  } catch (error) {
    compareState = {
      local,
      remote: null,
      rows: [],
      error: error instanceof Error ? error.message : String(error)
    };
    statusLine = null;
  }

  view = "diagnostics";
  await render();
}

function chapterIdFromNode(nodeId) {
  if (nodeId.startsWith("ch-")) {
    return nodeId.slice(3);
  }
  if (nodeId.startsWith("link-")) {
    const rest = nodeId.slice("link-".length);
    let best = null;
    for (const chapter of CATALOG.chapters) {
      const prefix = `${chapter.id}-`;
      if (rest.startsWith(prefix) && (best === null || chapter.id.length > best.length)) {
        best = chapter.id;
      }
    }
    return best;
  }
  return null;
}

function appletIdFromRunNode(nodeId) {
  if (nodeId.startsWith("applet-run-")) {
    return nodeId.slice("applet-run-".length);
  }
  return null;
}

function appletIdFromDevStudioNode(nodeId) {
  if (nodeId.startsWith("applet-devstudio-")) {
    return nodeId.slice("applet-devstudio-".length);
  }
  return null;
}

function appletIdFromPreviewNode(nodeId) {
  if (nodeId.startsWith("applet-preview-")) {
    return nodeId.slice("applet-preview-".length);
  }
  if (nodeId.startsWith("applet-stoppreview-")) {
    return nodeId.slice("applet-stoppreview-".length);
  }
  return null;
}

async function handleEvent({ nodeId, event, value }) {
  if (event === "hb.grantintro.dismiss") {
    await dismissGrantIntro();
    return;
  }

  if (event === "hb.toc") {
    await openToc();
    return;
  }

  if (event === "hb.diagnostics") {
    await openDiagnostics();
    return;
  }

  if (event === "hb.openchapter") {
    const id = chapterIdFromNode(nodeId);
    if (id !== null) {
      await openChapter(id);
    }
    return;
  }

  if (event === "hb.runapplet") {
    const id = appletIdFromRunNode(nodeId);
    if (id !== null) {
      await runAppletInline(id);
    }
    return;
  }

  if (event === "hb.runpreview") {
    const id = appletIdFromPreviewNode(nodeId);
    if (id !== null) {
      await runAppletPreviewSlot(id);
    }
    return;
  }

  if (event === "hb.stoppreview") {
    await stopAppletPreview();
    return;
  }

  if (event === "hb.devstudio") {
    const id = appletIdFromDevStudioNode(nodeId);
    if (id !== null) {
      await exportAppletToDevStudio(id);
    }
    return;
  }

  if (event === "hb.runall") {
    await runAllDiagnostics();
    return;
  }

  if (event === "hb.export") {
    await exportReport();
    return;
  }

  if (event === "hb.compare.input") {
    compareInput = typeof value === "string" ? value : String(value ?? "");
    return;
  }

  if (event === "hb.compare") {
    await compareReport();
  }
}

ui.onEvent((event) => {
  void handleEvent(event).catch(async (error) => {
    statusLine = `Error: ${error instanceof Error ? error.message : String(error)}`;
    await render();
  });
});

await ensureSeeds();

const grantIntroSeen = await kvGetText(GRANT_INTRO_KEY);
if (grantIntroSeen !== "1") {
  view = "grant-intro";
} else {
  const saved = await kvGetText(POSITION_KEY);
  if (saved !== null && findChapter(saved) !== null) {
    chapterId = saved;
    view = "chapter";
  } else {
    view = "toc";
  }
}

const cachedReport = await kvGetText(LAST_REPORT_KEY);
if (cachedReport !== null) {
  try {
    compareState = { ...compareState, local: JSON.parse(cachedReport) };
  } catch {
    // ignore corrupt cache
  }
}

await render();
